// Menú "⋯" con acciones de tarjeta (avanzar, volver, editar, eliminar).
const CardMenu = ({ items = [] }) => {
  const [open, setOpen] = useState(false);
  const [coords, setCoords] = useState({ top: 0, left: 0 });
  const btnRef = useRef(null);
  const menuRef = useRef(null);

  useEffect(() => {
    if (!open) return undefined;
    const onDoc = (e) => {
      if (
        menuRef.current?.contains(e.target) ||
        btnRef.current?.contains(e.target)
      )
        return;
      setOpen(false);
    };
    const onKey = (e) => {
      if (e.key === "Escape") setOpen(false);
    };
    const onScroll = () => setOpen(false);
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    window.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onScroll);
    return () => {
      document.removeEventListener("mousedown", onDoc);
      document.removeEventListener("keydown", onKey);
      window.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onScroll);
    };
  }, [open]);

  if (!items.length) return null;

  const toggle = (e) => {
    e.stopPropagation();
    if (!open && btnRef.current) {
      const r = btnRef.current.getBoundingClientRect();
      const menuWidth = 190;
      let left = r.right - menuWidth;
      if (left < 8) left = 8;
      setCoords({ top: r.bottom + 6, left });
    }
    setOpen((o) => !o);
  };

  return (
    <>
      <button
        ref={btnRef}
        onClick={toggle}
        aria-label="Más acciones"
        aria-haspopup="true"
        aria-expanded={open}
        className="p-1 rounded-md text-slate-400 hover:text-slate-600 dark:text-slate-500 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
      >
        <Icon name="MoreHorizontal" size={16} />
      </button>
      {open && (
        <div
          ref={menuRef}
          onClick={(e) => e.stopPropagation()}
          style={{
            position: "fixed",
            top: coords.top,
            left: coords.left,
            width: 190,
            zIndex: 9999,
          }}
          className="py-1.5 rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 shadow-xl shadow-black/10 dark:shadow-black/50 fade-in"
        >
          {items.map((it) => (
            <button
              key={it.key}
              disabled={it.disabled}
              onClick={(e) => {
                e.stopPropagation();
                setOpen(false);
                it.onClick?.();
              }}
              className={`w-full flex items-center gap-2.5 px-3 py-2 text-left text-[13px] font-semibold transition-colors disabled:opacity-40 ${
                it.danger
                  ? "text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-500/10"
                  : "text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800"
              }`}
            >
              <Icon name={it.icon} size={15} /> {it.label}
            </button>
          ))}
        </div>
      )}
    </>
  );
};

// Tarjeta compartida: compacta, navegable y consistente en todas las salas.
const FileDropHint = ({ active, label = "Suelta el archivo aquí" }) => {
  if (!active) return null;
  return (
    <div className="pointer-events-none absolute inset-0 z-20 flex items-center justify-center rounded-[inherit] border-2 border-dashed border-[var(--primary)] bg-[color-mix(in_srgb,var(--primary-soft)_88%,transparent)]">
      <p className="px-3 text-center text-sm font-semibold text-[var(--text)]">{label}</p>
    </div>
  );
};

const KanbanCard = ({
  onClick,
  draggable,
  onDragStart,
  onDragEnd,
  onDropFiles,
  onCardDragOver,
  onCardDrop,
  reorderable = false,
  accentTone,
  isOverdue,
  client,
  rank,
  badges = [],
  title,
  notes,
  due,
  assignee,
  menuItems = [],
  selected = false,
  statusControl = null,
  activityAction = null,
}) => {
  const [fileOver, setFileOver] = useState(false);
  const accent = isOverdue
    ? "border-l-red-500"
    : ACCENT_BORDER[accentTone] || "border-l-transparent";
  return (
    <div
      role="button"
      tabIndex={0}
      aria-label={`Abrir tarea ${title}`}
      onClick={onClick}
      onKeyDown={(event) => {
        if (
          event.target === event.currentTarget &&
          (event.key === "Enter" || event.key === " ")
        ) {
          event.preventDefault();
          onClick?.();
        }
      }}
      draggable={draggable ? "true" : undefined}
      onDragStart={onDragStart}
      onDragEnd={(event) => {
        setFileOver(false);
        onDragEnd?.(event);
      }}
      onDragEnter={(event) => {
        if (onDropFiles && hasFileDrag(event)) {
          event.preventDefault();
          event.stopPropagation();
          setFileOver(true);
          return;
        }
        if (onCardDragOver && !hasFileDrag(event)) {
          event.preventDefault();
          event.stopPropagation();
        }
      }}
      onDragOver={(event) => {
        if (onDropFiles && hasFileDrag(event)) {
          event.preventDefault();
          event.stopPropagation();
          event.dataTransfer.dropEffect = "copy";
          setFileOver(true);
          return;
        }
        if (onCardDragOver && !hasFileDrag(event)) {
          event.preventDefault();
          event.stopPropagation();
          event.dataTransfer.dropEffect = "move";
          onCardDragOver(event);
        }
      }}
      onDragLeave={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) setFileOver(false);
      }}
      onDrop={(event) => {
        if (onDropFiles && hasFileDrag(event)) {
          event.preventDefault();
          event.stopPropagation();
          setFileOver(false);
          const files = filesFromDrop(event);
          if (files.length) onDropFiles(files);
          return;
        }
        if (onCardDrop && !hasFileDrag(event)) {
          event.preventDefault();
          event.stopPropagation();
          onCardDrop(event);
        }
      }}
      className={`task-card group relative cursor-pointer rounded-xl border border-[var(--border)] border-l-[3px] bg-white p-4 transition-[border-color,background-color,transform] duration-200 hover:-translate-y-px hover:border-[var(--border-strong)] focus-visible:outline-none dark:border-white/10 dark:bg-[var(--surface-raised)] dark:hover:border-white/20 ${selected || fileOver ? "ring-2 ring-[var(--status-yellow-text)] dark:ring-[var(--status-yellow-text)]" : ""} ${accent}`}
    >
      <FileDropHint active={fileOver} label="Soltar para adjuntar" />
      <div className="flex items-start justify-between gap-2 mb-1.5 min-h-[20px]">
        <div className="min-w-0 flex-1">
          {client && (
            <span className="inline-flex max-w-full items-center gap-1.5 text-[11px] font-semibold uppercase tracking-[0.07em] text-slate-500 dark:text-slate-400">
              <Icon name="Briefcase" size={10} className="shrink-0" />
              <span className="truncate">{client}</span>
            </span>
          )}
        </div>
        <div className="flex items-center gap-0.5 shrink-0">
          {reorderable && (
            <span
              className="text-slate-300 dark:text-slate-600"
              title="Arrastra para priorizar"
              aria-hidden="true"
            >
              <Icon name="GripVertical" size={14} />
            </span>
          )}
          {rank != null && (
            <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 bg-slate-100 dark:bg-slate-800 rounded px-1.5 py-0.5">
              #{rank}
            </span>
          )}
          {menuItems.length > 0 && (
            <span className="opacity-70 group-hover:opacity-100 transition-opacity">
              <CardMenu items={menuItems} />
            </span>
          )}
        </div>
      </div>

      <p className="mb-2.5 line-clamp-2 text-[15px] font-semibold leading-snug text-slate-800 dark:text-slate-100">
        {title}
      </p>

      {badges.length > 0 && (
        <div className="mb-2.5 flex flex-wrap gap-1.5">
          {badges.map((b, i) => (
            <span
              key={i}
              className={`text-[10px] font-bold uppercase tracking-wide px-1.5 py-0.5 rounded ${
                b.className || PILL_TONES[b.tone] || PILL_TONES.slate
              }`}
            >
              {b.label}
            </span>
          ))}
        </div>
      )}

      {statusControl && (
        <label
          className="mb-2.5 block"
          onClick={(event) => event.stopPropagation()}
          onPointerDown={(event) => event.stopPropagation()}
          onTouchStart={(event) => event.stopPropagation()}
        >
          <span className="mb-1.5 block text-[10px] font-semibold uppercase tracking-[0.08em] text-slate-500 dark:text-slate-400">
            Estado
          </span>
          <span className="relative block">
            <select
              value={statusControl.value}
              onChange={(event) => statusControl.onChange(event.target.value)}
              onClick={(event) => event.stopPropagation()}
              onDragStart={(event) => event.stopPropagation()}
              aria-label={`Cambiar estado de ${title}`}
              className="min-h-11 w-full appearance-none rounded-lg border border-[var(--border)] bg-[var(--surface-subtle)] px-3 py-2 pr-10 text-sm font-semibold text-slate-700 outline-none transition-colors focus:border-blue-500 focus:ring-2 focus:ring-blue-500/25 dark:border-white/10 dark:bg-[var(--surface)] dark:text-slate-200 lg:min-h-9 lg:py-1.5 lg:text-xs"
            >
              {statusControl.options.map((option) => (
                <option key={option.id} value={option.id}>
                  {option.label || option.title}
                </option>
              ))}
            </select>
            <Icon
              name="ChevronDown"
              size={14}
              className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-slate-500"
            />
          </span>
        </label>
      )}

      {notes && (
        <p className="mb-2 line-clamp-1 text-[11.5px] leading-snug text-slate-400 dark:text-slate-500">
          {notes}
        </p>
      )}

      <div className="flex items-center justify-between gap-2 border-t border-slate-100 pt-3 dark:border-white/5">
        {due ? (
          <span
            className={`inline-flex items-center gap-1 text-[11px] font-semibold ${
              due.tone === "red"
                ? "text-red-500 dark:text-red-400"
                : due.tone === "amber"
                  ? "text-amber-600 dark:text-amber-400"
                  : "text-slate-400 dark:text-slate-500"
            }`}
          >
            <Icon name="CalendarDays" size={12} className="shrink-0" />
            {due.label}
          </span>
        ) : (
          <span />
        )}
        {activityAction && (
          <button
            type="button"
            onClick={(event) => {
              event.stopPropagation();
              activityAction.onClick?.();
            }}
            onPointerDown={(event) => event.stopPropagation()}
            onTouchStart={(event) => event.stopPropagation()}
            className={`production-log-trigger ${activityAction.active ? "is-active" : ""}`}
            aria-label={`Abrir bitácora de ${title}`}
          >
            <Icon name="ClipboardList" size={13} />
            <span>Bitácora</span>
            <span className="production-log-trigger-count">
              {activityAction.count || 0}
            </span>
          </button>
        )}
        {assignee ? (
          assignee.photo ? (
            <img
              src={assignee.photo}
              alt={assignee.name}
              title={assignee.name}
              className="w-6 h-6 rounded-full object-cover shrink-0 border border-black/5 dark:border-white/10"
            />
          ) : (
            <span
              title={assignee.name}
              className={`w-6 h-6 rounded-full flex items-center justify-center text-[9px] font-bold shrink-0 ${assignee.className}`}
            >
              {assignee.initials}
            </span>
          )
        ) : (
          <span className="w-6 h-6 rounded-full border border-dashed border-slate-300 dark:border-slate-600 flex items-center justify-center text-slate-300 dark:text-slate-600 shrink-0">
            <Icon name="User" size={11} />
          </span>
        )}
      </div>
    </div>
  );
};

// Columna de tablero compartida (cabecera discreta + cuerpo + añadir).
const KanbanColumn = ({
  dotColor = "slate",
  title,
  subtitle,
  count,
  onAdd,
  onDragOver,
  onDragLeave,
  onDrop,
  isEmpty,
  children,
}) => {
  const columnColor = getDashboardPalette(dotColor).strong;
  return (
    <section
      className="task-room-column flex h-[calc(100dvh-15rem)] min-h-[32rem] w-[88vw] shrink-0 snap-start flex-col overflow-hidden rounded-xl border border-[var(--border)] bg-[var(--surface-muted)] transition-colors dark:border-white/10 dark:bg-[var(--surface)] sm:w-[24rem] lg:h-full lg:min-h-0 lg:w-auto lg:shrink"
      onDragOver={onDragOver}
      onDragLeave={onDragLeave}
      onDrop={onDrop}
      aria-label={`${title}: ${count} tareas`}
    >
      <header className="flex shrink-0 items-start justify-between gap-3 border-b border-[var(--border)] bg-[var(--surface-subtle)] px-4 py-3.5 dark:border-white/10 dark:bg-[var(--surface)]">
        <div className="min-w-0">
          <div className="flex min-w-0 items-center gap-2.5">
            <span
              className="h-2.5 w-2.5 shrink-0 rounded-full"
              style={{ backgroundColor: columnColor }}
            />
            <span className="truncate text-sm font-semibold text-[var(--text)] dark:text-[var(--text)]">
              {title}
            </span>
            <span className="mono-meta shrink-0 rounded-md bg-[var(--surface-muted)] px-2 py-0.5 text-[11px] font-semibold text-[var(--text-muted)] dark:bg-[var(--surface-muted)] dark:text-[var(--text-muted)]">
              {count}
            </span>
          </div>
          {subtitle && (
            <p className="mt-1.5 pl-5 text-[11px] text-slate-500 dark:text-slate-400">
              {subtitle}
            </p>
          )}
        </div>
        {onAdd && (
          <button
            type="button"
            onClick={onAdd}
            aria-label={`Añadir tarea en ${title}`}
            title="Añadir tarea"
            className="flex h-8 min-h-0 w-8 min-w-0 items-center justify-center rounded-md text-[var(--text-muted)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)] dark:text-[var(--text-muted)] dark:hover:bg-[var(--surface-muted)] dark:hover:text-[var(--text)]"
          >
            <Icon name="Plus" size={15} />
          </button>
        )}
      </header>
      <div className="custom-scroll flex-1 space-y-3 overflow-y-auto overscroll-contain p-3">
        {isEmpty && (
          <div className="flex h-full min-h-40 select-none flex-col items-center justify-center gap-2 text-slate-300 dark:text-slate-600">
            <Icon name="Inbox" size={24} />
            <span className="text-[11px] font-semibold">Sin tareas en esta etapa</span>
          </div>
        )}
        {children}
      </div>
    </section>
  );
};

const KanbanStage = ({
  title,
  dotColor = "slate",
  tasks,
  renderTask,
  showHeader = true,
  collapsible = false,
  collapsedLimit = 3,
  onDragOver,
  onDragLeave,
  onDrop,
}) => {
  const [expanded, setExpanded] = useState(false);
  const color = getDashboardPalette(dotColor).strong;
  const canCollapse = collapsible && tasks.length > collapsedLimit;
  const visibleTasks = canCollapse && !expanded ? tasks.slice(0, collapsedLimit) : tasks;

  return (
    <section
      className="rounded-lg border border-transparent transition-colors [&.drag-over]:border-[var(--status-yellow-text)] [&.drag-over]:bg-[var(--status-yellow-text)]/5"
      onDragOver={onDragOver}
      onDragLeave={onDragLeave}
      onDrop={onDrop}
      aria-label={`${title}: ${tasks.length} tareas`}
    >
      {showHeader && (
        <div className="mb-2 flex items-center justify-between rounded-lg border border-[var(--border)] bg-[var(--surface-subtle)] px-3 py-2.5 dark:border-white/10 dark:bg-[var(--surface-muted)]">
          <div className="flex min-w-0 items-center gap-2">
            <span className="h-2 w-2 shrink-0 rounded-full" style={{ backgroundColor: color }} />
            <span className="truncate text-[11px] font-semibold uppercase tracking-[0.07em] text-slate-600 dark:text-slate-300">
              {title}
            </span>
            <span className="rounded bg-[var(--surface-muted)] px-1.5 py-0.5 text-[10px] font-semibold text-slate-500 dark:bg-[var(--surface-muted)] dark:text-slate-400">
              {tasks.length}
            </span>
          </div>
          {canCollapse && (
            <button
              type="button"
              onClick={() => setExpanded((value) => !value)}
              className="flex h-7 w-7 items-center justify-center rounded-md text-slate-500 hover:bg-black/5 dark:text-slate-400 dark:hover:bg-white/5"
              aria-label={expanded ? `Contraer ${title}` : `Expandir ${title}`}
            >
              <Icon name={expanded ? "ChevronUp" : "ChevronDown"} size={14} />
            </button>
          )}
        </div>
      )}
      <div className="space-y-2.5">
        {visibleTasks.map((task) => renderTask(task))}
      </div>
      {canCollapse && !expanded && (
        <button
          type="button"
          onClick={() => setExpanded(true)}
          className="mt-2 flex w-full items-center justify-center gap-1.5 rounded-lg border border-dashed border-[var(--border-strong)] px-3 py-2.5 text-xs font-semibold text-slate-500 hover:border-[var(--border-strong)] hover:text-slate-700 dark:border-white/15 dark:text-slate-400 dark:hover:border-white/25 dark:hover:text-slate-200"
        >
          Ver {tasks.length - collapsedLimit} más
          <Icon name="ChevronDown" size={14} />
        </button>
      )}
    </section>
  );
};

const TaskRoomInspector = ({
  task,
  client,
  assignee,
  status,
  onClose,
  onOpenFull,
}) => {
  if (!task) return null;
  const checklist = Array.isArray(task.checklist) ? task.checklist : [];
  const completed = checklist.filter((item) => item.done).length;
  const progress = checklist.length ? Math.round((completed / checklist.length) * 100) : 0;
  const activity = [
    ...(Array.isArray(task.comments)
      ? task.comments.map((item) => ({
          id: item.id,
          author: item.authorName || "Equipo",
          text: item.text,
          date: item.createdAt,
        }))
      : []),
    ...(Array.isArray(task.timeEntries)
      ? task.timeEntries.map((item) => ({
          id: item.id,
          author: item.authorName || "Equipo",
          text: "Registró tiempo en la tarea",
          date: item.loggedAt,
        }))
      : []),
  ]
    .sort((a, b) => new Date(b.date || 0) - new Date(a.date || 0))
    .slice(0, 3);
  const priority = task.priority
    ? task.priority.charAt(0).toUpperCase() + task.priority.slice(1)
    : "Normal";
  const isOverdue = isDateBeforeDateString(task.date, getHondurasTodayStr()) &&
    !isCompletedStatus(task.status);

  return (
    <aside className="task-room-inspector fixed inset-x-3 bottom-3 top-20 z-40 flex min-h-0 flex-col overflow-hidden rounded-xl border border-[var(--border)] bg-[var(--surface-subtle)] shadow-2xl dark:border-white/10 dark:bg-[var(--surface)] 2xl:static 2xl:z-auto 2xl:shadow-none">
      <div className="custom-scroll flex-1 overflow-y-auto p-5">
        <div className="mb-6 flex items-start justify-between gap-3">
          <div className="min-w-0">
            {client && (
              <p className="mb-2 inline-flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-[0.08em] text-slate-500 dark:text-slate-400">
                <Icon name="Briefcase" size={11} />
                {client}
              </p>
            )}
            <h3 className="text-lg font-semibold leading-snug text-slate-900 dark:text-[var(--text)]">
              {task.title}
            </h3>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg text-slate-500 hover:bg-black/5 dark:text-slate-400 dark:hover:bg-white/5"
            aria-label="Cerrar inspector"
          >
            <Icon name="X" size={18} />
          </button>
        </div>

        <div className="mb-6 grid grid-cols-2 gap-2">
          <div className="rounded-lg border border-[var(--border)] bg-white px-3 py-2.5 dark:border-white/10 dark:bg-[var(--surface-raised)]">
            <p className="text-[9px] font-semibold uppercase tracking-[0.08em] text-slate-400">Estado</p>
            <p className="mt-1 text-xs font-semibold text-slate-700 dark:text-slate-200">{status?.title || "Sin estado"}</p>
          </div>
          <div className={`rounded-lg border px-3 py-2.5 ${priority.toLowerCase() === "urgente" ? "border-red-200 bg-red-50 text-red-700 dark:border-red-500/20 dark:bg-red-500/10 dark:text-red-300" : "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-500/20 dark:bg-amber-500/10 dark:text-amber-300"}`}>
            <p className="text-[9px] font-semibold uppercase tracking-[0.08em] opacity-70">Prioridad</p>
            <p className="mt-1 text-xs font-semibold">{priority}</p>
          </div>
        </div>

        <div className="mb-6 grid grid-cols-2 gap-4 border-b border-[var(--border)] pb-6 dark:border-white/10">
          <div>
            <p className="mb-2 text-[9px] font-semibold uppercase tracking-[0.08em] text-slate-400">Responsable</p>
            <div className="flex items-center gap-2">
              {assignee ? (
                <>
                  {assignee.photo ? (
                    <img src={assignee.photo} alt="" className="h-8 w-8 rounded-full object-cover" />
                  ) : (
                    <span className={`flex h-8 w-8 items-center justify-center rounded-full text-[10px] font-bold ${assignee.className}`}>
                      {assignee.initials}
                    </span>
                  )}
                  <span className="truncate text-xs font-semibold text-slate-700 dark:text-slate-200">{assignee.name}</span>
                </>
              ) : (
                <span className="text-xs text-slate-500">Sin asignar</span>
              )}
            </div>
          </div>
          <div>
            <p className="mb-2 text-[9px] font-semibold uppercase tracking-[0.08em] text-slate-400">Vencimiento</p>
            <p className={`inline-flex items-center gap-1.5 text-xs font-semibold ${isOverdue ? "text-red-500" : "text-slate-700 dark:text-slate-200"}`}>
              <Icon name="CalendarDays" size={14} />
              {formatShortDate(task.date, task.time)}{isOverdue ? " · atrasada" : ""}
            </p>
          </div>
        </div>

        {task.assignedByName && (
          <div className="mb-6 flex items-center gap-2.5 border-b border-[var(--border)] pb-6 dark:border-white/10">
            <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-violet-100 text-violet-700 dark:bg-violet-500/20 dark:text-violet-300">
              <Icon name="UserCheck" size={15} />
            </span>
            <div className="min-w-0">
              <p className="text-[9px] font-semibold uppercase tracking-[0.08em] text-slate-400">
                Creada por
              </p>
              <p className="mt-0.5 truncate text-xs font-semibold text-slate-700 dark:text-slate-200">
                {task.assignedByName}
              </p>
            </div>
          </div>
        )}

        <div className="mb-6 border-b border-[var(--border)] pb-6 dark:border-white/10">
          <div className="mb-2.5 flex items-center justify-between">
            <p className="text-[9px] font-semibold uppercase tracking-[0.08em] text-slate-400">Progreso</p>
            <span className="text-xs font-semibold text-slate-500">{progress}%</span>
          </div>
          <div className="mb-2 h-1.5 overflow-hidden rounded-full bg-[var(--surface-muted)] dark:bg-white/10">
            <span className="block h-full rounded-full bg-[var(--status-yellow-text)] transition-[width]" style={{ width: `${progress}%` }} />
          </div>
          <p className="text-xs text-slate-500 dark:text-slate-400">
            {checklist.length ? `${completed} de ${checklist.length} completadas` : "Sin checklist"}
          </p>
        </div>

        {task.notes && (
          <div className="mb-6 border-b border-[var(--border)] pb-6 dark:border-white/10">
            <p className="mb-2 text-[9px] font-semibold uppercase tracking-[0.08em] text-slate-400">Descripción</p>
            <p className="whitespace-pre-wrap text-sm leading-relaxed text-slate-600 dark:text-slate-300">{task.notes}</p>
          </div>
        )}

        <div>
          <p className="mb-3 text-[9px] font-semibold uppercase tracking-[0.08em] text-slate-400">Actividad reciente</p>
          {activity.length ? (
            <div className="space-y-3">
              {activity.map((item) => (
                <div key={item.id} className="flex gap-2.5">
                  <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-[var(--status-green-text)] text-[9px] font-bold text-white">
                    {getInitials(item.author)}
                  </span>
                  <div className="min-w-0">
                    <p className="text-xs font-semibold text-slate-700 dark:text-slate-200">{item.author}</p>
                    <p className="mt-0.5 line-clamp-2 text-xs leading-relaxed text-slate-500 dark:text-slate-400">{item.text}</p>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-xs text-slate-500 dark:text-slate-400">Sin actividad registrada.</p>
          )}
        </div>
      </div>
      <div className="border-t border-[var(--border)] p-4 dark:border-white/10">
        <button
          type="button"
          onClick={onOpenFull}
          className="flex min-h-11 w-full items-center justify-center gap-2 rounded-lg bg-[var(--primary)] px-4 py-3 text-sm font-semibold text-[var(--primary-contrast)] transition-colors hover:bg-[var(--primary-hover)] dark:bg-[var(--primary)] dark:text-[var(--primary-contrast)] dark:hover:bg-[var(--primary-hover)]"
        >
          Abrir tarea completa
          <Icon name="ExternalLink" size={15} />
        </button>
      </div>
    </aside>
  );
};

const formatProductionLogTimestamp = (value) => {
  const date = value ? new Date(value) : null;
  if (!date || Number.isNaN(date.getTime())) return "Ahora";
  return new Intl.DateTimeFormat("es-HN", {
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
};

const ProductionLogPanel = ({
  task,
  onClose,
  onOpenFull,
  onAddEntry,
  currentUserProfile,
}) => {
  const [draft, setDraft] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [optimisticEntries, setOptimisticEntries] = useState([]);

  useEffect(() => {
    setDraft("");
    setError("");
    setOptimisticEntries([]);
  }, [task?._key]);

  useEffect(() => {
    const handleEscape = (event) => {
      if (event.key === "Escape") onClose?.();
    };
    document.addEventListener("keydown", handleEscape);
    return () => document.removeEventListener("keydown", handleEscape);
  }, [onClose]);

  if (!task) return null;

  const storedEntries = Array.isArray(task.comments) ? task.comments : [];
  const storedIds = new Set(storedEntries.map((entry) => entry.id));
  const entries = [
    ...optimisticEntries.filter((entry) => !storedIds.has(entry.id)),
    ...storedEntries,
  ].sort(
    (left, right) =>
      new Date(right.createdAt || 0).getTime() -
      new Date(left.createdAt || 0).getTime(),
  );
  const responsibleName =
    task._assignee?.name || task._ownerText || "Sin responsable asignado";
  const currentAuthor =
    currentUserProfile?.name || currentUserProfile?.email || "Usuario";
  const statusMeta = getModuleStatusMeta(task._status, "production");
  const taskDate = task._date ? formatShortDate(task._date) : "Sin fecha";
  const currentAuthorInitials = getInitials(currentAuthor);

  const handleSubmit = async (event) => {
    event.preventDefault();
    const text = draft.trim();
    if (!text || saving || !onAddEntry) return;
    setSaving(true);
    setError("");
    try {
      const savedEntry = await onAddEntry(task, task._taskType, text);
      if (savedEntry) {
        setOptimisticEntries((current) => [savedEntry, ...current]);
      }
      setDraft("");
    } catch (saveError) {
      console.error("[production-log]", saveError);
      setError("No pudimos guardar la nota. Revisa tu conexión e intenta de nuevo.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div
      className="production-log-overlay"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose?.();
      }}
      role="presentation"
    >
    <aside
      className="production-log-panel"
      role="dialog"
      aria-modal="true"
      aria-labelledby="production-log-title"
      tabIndex="-1"
    >
      <header className="production-log-panel-header">
        <div className="production-log-panel-topline">
          <p className="production-log-kicker">
            <Icon name="ClipboardList" size={14} />
            Bitácora
          </p>
          <div className="production-log-panel-actions">
            <span className={`production-log-status is-${statusMeta.tone}`}>
              <span aria-hidden="true" />
              {statusMeta.label}
            </span>
            <button
              type="button"
              onClick={onClose}
              className="production-log-close"
              aria-label="Cerrar bitácora"
              autoFocus
            >
              <Icon name="X" size={18} />
            </button>
          </div>
        </div>
        <h3 id="production-log-title">{task._title}</h3>
        <div className="production-log-overview">
          <div>
            <Icon name="User" size={14} />
            <span>
              <small>Responsable</small>
              <strong>{responsibleName}</strong>
            </span>
          </div>
          <div>
            <Icon name="CalendarDays" size={14} />
            <span>
              <small>Fecha</small>
              <strong>{taskDate}</strong>
            </span>
          </div>
          <div>
            <Icon name="FileText" size={14} />
            <span>
              <small>Registros</small>
              <strong>{entries.length}</strong>
            </span>
          </div>
        </div>
      </header>

      <form className="production-log-composer" onSubmit={handleSubmit}>
        <div className="production-log-composer-heading">
          <span><Icon name="Pencil" size={16} /></span>
          <div>
            <label htmlFor={`production-log-${task.id}`}>Nuevo registro</label>
            <p>Deja una nota concreta para que el siguiente turno sepa qué ocurrió.</p>
          </div>
        </div>
        <div className="production-log-editor">
          <textarea
            id={`production-log-${task.id}`}
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if ((event.ctrlKey || event.metaKey) && event.key === "Enter") {
                handleSubmit(event);
              }
            }}
            maxLength={1600}
            placeholder="¿Qué pasó, qué decisión se tomó y qué necesita saber el siguiente responsable?"
            disabled={saving || !onAddEntry}
            aria-keyshortcuts="Control+Enter Meta+Enter"
          />
          <div className="production-log-editor-footer">
            <span className="production-log-author">
              <span aria-hidden="true">{currentAuthorInitials}</span>
              <span>
                <small>Registrado por</small>
                <strong>{currentAuthor}</strong>
              </span>
            </span>
            <span className="production-log-counter">{draft.length} / 1,600</span>
          </div>
        </div>
        {error && (
          <p className="production-log-error" role="alert">
            {error}
          </p>
        )}
        <div className="production-log-composer-actions">
          <span><Icon name="Zap" size={13} /> Ctrl + Enter para guardar</span>
          <button type="submit" disabled={!draft.trim() || saving || !onAddEntry}>
            <Icon name={saving ? "Loader2" : "Send"} size={16} className={saving ? "animate-spin" : ""} />
            {saving ? "Guardando…" : "Guardar registro"}
          </button>
        </div>
      </form>

      <div className="production-log-timeline custom-scroll" aria-live="polite">
        <div className="production-log-timeline-heading">
          <div>
            <span><Icon name="Clock" size={15} /></span>
            <div>
              <p>Historial de la tarea</p>
              <small>La información más reciente aparece primero.</small>
            </div>
          </div>
          <strong>{entries.length} {entries.length === 1 ? "nota" : "notas"}</strong>
        </div>
        {entries.length ? (
          <div className="production-log-entries">
            {entries.map((entry, index) => {
              const author = entry.authorName || "Equipo";
              return (
                <article className="production-log-entry" key={entry.id}>
                  <span className="production-log-avatar" aria-hidden="true">
                    {getInitials(author)}
                  </span>
                  <div className="production-log-entry-body">
                    <div className="production-log-entry-meta">
                      <div>
                        <strong>{author}</strong>
                        <span>Registro {String(entries.length - index).padStart(2, "0")}</span>
                      </div>
                      <time dateTime={entry.createdAt || undefined}>
                        {formatProductionLogTimestamp(entry.createdAt)}
                      </time>
                    </div>
                    <p>{entry.text}</p>
                  </div>
                </article>
              );
            })}
          </div>
        ) : (
          <div className="production-log-empty">
            <span><Icon name="ClipboardList" size={22} /></span>
            <strong>Aún no hay registros</strong>
            <p>Documenta aquí decisiones, bloqueos, cambios y entregas de esta tarea.</p>
          </div>
        )}
      </div>

      <footer className="production-log-footer">
        <button type="button" onClick={onOpenFull}>
          <span>
            <Icon name="ExternalLink" size={15} />
            Ver tarea completa
          </span>
          <Icon name="ArrowRight" size={14} />
        </button>
      </footer>
    </aside>
    </div>
  );
};

const TaskRoomWorkspace = ({
  groups,
  onAdd,
  canAdd = true,
  renderTask,
  onDragOver,
  onDragLeave,
  onDrop,
  inspector,
}) => (
  <div className="task-room-workspace grid min-h-0 flex-1 gap-3">
    <div className={`task-room-board flex min-h-0 gap-3 overflow-x-auto pb-4 snap-x snap-mandatory kanban-mobile-scroll lg:grid lg:overflow-hidden lg:pb-0 ${groups.length > 3 ? "task-room-board-4 lg:grid-cols-4" : "lg:grid-cols-3"}`}>
      {groups.map((group) => {
        const count = group.stages.reduce((total, stage) => total + stage.tasks.length, 0);
        return (
          <KanbanColumn
            key={group.id}
            dotColor={group.color}
            title={group.title}
            subtitle={group.subtitle}
            count={count}
            onAdd={canAdd ? onAdd : undefined}
            isEmpty={count === 0}
          >
            {group.stages.map((stage) => (
              <KanbanStage
                key={stage.id}
                title={stage.title}
                dotColor={stage.color}
                tasks={stage.tasks}
                renderTask={(task) => renderTask(task, stage)}
                showHeader={group.stages.length > 1}
                collapsible={stage.collapsible}
                collapsedLimit={stage.collapsedLimit}
                onDragOver={onDragOver}
                onDragLeave={onDragLeave}
                onDrop={(event) => onDrop(event, stage.id)}
              />
            ))}
          </KanbanColumn>
        );
      })}
    </div>
    {inspector}
  </div>
);

const DateHeader = ({
  currentDate,
  setCurrentDate,
  filterMode,
  setFilterMode,
  ownershipFilter = "all",
  setOwnershipFilter,
  title,
  onAdd,
  btnColor,
  btnIcon,
  searchTerm,
  setSearchTerm,
  rangeStart,
  setRangeStart,
  rangeEnd,
  setRangeEnd,
  onLoadHistory,
  historyLoaded = false,
  historyLoading = false,
  taskCount = 0,
}) => {
  const today = getHondurasTodayStr();
  const hasRangeSupport = Boolean(setRangeStart && setRangeEnd);
  const effectiveRangeStart = rangeStart || today;
  const effectiveRangeEnd = rangeEnd || today;
  const periodDate = new Date(`${currentDate || today}T12:00:00`);
  const periodLabel = new Intl.DateTimeFormat("es-HN", {
    month: "long",
    year: "numeric",
  }).format(periodDate);

  const handleRangeStartChange = (e) => {
    const val = e.target.value;
    setRangeStart(val);
    if (compareDateOnlyStrings(val, effectiveRangeEnd) > 0) setRangeEnd(val);
  };
  const handleRangeEndChange = (e) => {
    const val = e.target.value;
    setRangeEnd(val);
    if (compareDateOnlyStrings(val, effectiveRangeStart) < 0)
      setRangeStart(val);
  };

  const segBase =
    "shrink-0 min-h-9 px-3 py-2 text-[12px] font-medium rounded-lg transition-colors flex items-center gap-1.5";
  const segActive =
    "bg-white text-[var(--text)] shadow-sm dark:bg-[var(--surface-muted)] dark:text-[var(--text)]";
  const segIdle =
    "text-slate-500 dark:text-slate-400 hover:bg-black/5 hover:text-slate-700 dark:hover:bg-white/5 dark:hover:text-slate-200";

  return (
    <header className="task-room-header shrink-0 border-b border-[var(--border)] pb-3 dark:border-white/10">
      <div className="mb-3 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div className="min-w-0">
          <h2 className="editorial-title truncate text-[clamp(1.75rem,3vw,2.5rem)] leading-none text-[var(--text)] dark:text-[var(--text)]">
            {title}
          </h2>
          <p className="mt-2 text-sm text-slate-500 dark:text-slate-400">
            {taskCount} {taskCount === 1 ? "tarea" : "tareas"} · {periodLabel.charAt(0).toUpperCase() + periodLabel.slice(1)}
          </p>
        </div>
        <div className="flex w-full flex-col items-stretch gap-2 sm:flex-row sm:items-center lg:w-auto">
          <SearchBar
            searchTerm={searchTerm}
            setSearchTerm={setSearchTerm}
            placeholder="Buscar tarea..."
          />
          <div className="shrink-0">
            <Button
              onClick={() =>
                onAdd(
                  filterMode === "date"
                    ? currentDate
                    : filterMode === "range"
                      ? effectiveRangeStart
                      : today,
                )
              }
              color={btnColor}
              icon={btnIcon}
              full
            >
              Nueva Tarea
            </Button>
          </div>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-2">
          <div className="flex max-w-full overflow-x-auto rounded-lg bg-[var(--surface-muted)] p-1 kanban-mobile-scroll dark:bg-[var(--surface-raised)]">
            <button
              onClick={() => setFilterMode("date")}
              className={`${segBase} ${filterMode === "date" ? segActive : segIdle}`}
            >
              <Icon name="CalendarDays" size={14} />
              Día específico
            </button>
            {hasRangeSupport && (
              <button
                onClick={() => setFilterMode("range")}
                className={`${segBase} ${filterMode === "range" ? segActive : segIdle}`}
              >
                <Icon name="CalendarRange" size={14} />
                Rango
              </button>
            )}
            <button
              onClick={() => setFilterMode("overdue")}
              className={`${segBase} ${filterMode === "overdue" ? "bg-[var(--status-red-bg)] text-[var(--status-red-text)] dark:bg-red-500/15 dark:text-red-300" : segIdle}`}
            >
              Atrasadas <Icon name="Flame" size={14} />
            </button>
            <button
              onClick={() => setFilterMode("all")}
              className={`${segBase} ${filterMode === "all" ? segActive : segIdle}`}
            >
              Este mes
            </button>
            {onLoadHistory && (
              <button
                onClick={async () => {
                  if (!historyLoaded) await onLoadHistory();
                  setFilterMode("history");
                }}
                disabled={historyLoading}
                className={`${segBase} ${filterMode === "history" ? segActive : segIdle}`}
              >
                <Icon name="Clock" size={14} />
                {historyLoading ? "Cargando" : "Histórico"}
              </button>
            )}
          </div>
          {setOwnershipFilter && (
            <div className="flex max-w-full overflow-x-auto rounded-lg bg-[var(--surface-muted)] p-1 kanban-mobile-scroll dark:bg-[var(--surface-raised)]">
              <button
                onClick={() => setOwnershipFilter("all")}
                className={`${segBase} ${ownershipFilter === "all" ? segActive : segIdle}`}
              >
                Todo el equipo
              </button>
              <button
                onClick={() => setOwnershipFilter("mine")}
                className={`${segBase} ${ownershipFilter === "mine" ? segActive : segIdle}`}
              >
                <Icon name="User" size={14} />
                Asignadas a mí
              </button>
            </div>
          )}
          {filterMode === "date" && (
            <div className="flex items-center gap-2">
              <input
                type="date"
                value={currentDate}
                onChange={(e) => setCurrentDate(e.target.value)}
                className="min-h-10 rounded-lg border border-[var(--border)] bg-white px-3 py-1.5 text-[13px] font-semibold text-slate-600 outline-none focus:border-[var(--focus)] dark:border-white/10 dark:bg-[var(--surface-raised)] dark:text-slate-300"
              />
              {currentDate === today && (
                <span className="text-[10px] bg-blue-100 dark:bg-blue-500/20 text-blue-700 dark:text-blue-400 font-bold px-2 py-1 rounded-full shrink-0">
                  Hoy
                </span>
              )}
            </div>
          )}
          {filterMode === "range" && hasRangeSupport && (
            <div className="flex items-center gap-2 flex-wrap">
              <input
                type="date"
                value={effectiveRangeStart}
                onChange={handleRangeStartChange}
                className="min-h-10 rounded-lg border border-[var(--border)] bg-white px-3 py-1.5 text-[13px] font-semibold text-slate-600 outline-none focus:border-[var(--focus)] dark:border-white/10 dark:bg-[var(--surface-raised)] dark:text-slate-300"
              />
              <span className="text-xs font-semibold text-slate-400">→</span>
              <input
                type="date"
                value={effectiveRangeEnd}
                min={effectiveRangeStart}
                onChange={handleRangeEndChange}
                className="min-h-10 rounded-lg border border-[var(--border)] bg-white px-3 py-1.5 text-[13px] font-semibold text-slate-600 outline-none focus:border-[var(--focus)] dark:border-white/10 dark:bg-[var(--surface-raised)] dark:text-slate-300"
              />
            </div>
          )}
      </div>
    </header>
  );
};

const MyDayStrip = ({
  tasks = [],
  profile,
  clients = [],
  today,
  onOpen,
  doneStatuses = [],
  linkedIds = [],
}) => {
  const todayKey = normalizeDateOnlyString(today) || getHondurasTodayStr();
  const items = tasks.filter((task) => {
    const status = task.status || task._status || "";
    if (doneStatuses.includes(status)) return false;
    if (profile && !isTaskAssignedToProfile(task, profile, linkedIds)) return false;
    const dates = taskDueDates(task);
    if (!dates.length) return false;
    return dates.some((date) => compareDateOnlyStrings(date, todayKey) <= 0);
  }).slice(0, 8);
  if (!items.length) return null;
  const clientName = (task) => clients.find((client) => client.id === task.clientId)?.name || "";
  return (
    <section className="rounded-xl border border-[var(--border)] bg-white px-3 py-3 dark:border-white/10 dark:bg-[var(--surface-raised)]">
      <p className="mb-2 text-[11px] font-black uppercase tracking-[0.14em] text-slate-500">
        Mi día · {items.length}
      </p>
      <div className="flex gap-2 overflow-x-auto">
        {items.map((task) => {
          const local = storedDueToViewer({
            date: task.date || task._date || "",
            time: task.time || task._time || "",
          });
          const overdue = taskDueDates(task).every((date) => compareDateOnlyStrings(date, todayKey) < 0);
          const label = [clientName(task), local.time, overdue ? "vencida" : ""].filter(Boolean).join(" · ");
          return (
            <button
              key={task.id || task._key}
              type="button"
              onClick={() => onOpen?.(task)}
              className="min-w-[180px] max-w-[240px] shrink-0 rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-left hover:border-slate-300 dark:border-white/10 dark:bg-slate-900/50"
            >
              <p className="truncate text-sm font-semibold text-slate-800 dark:text-slate-100">
                {task.title || task._title || "Sin título"}
              </p>
              <p className="mt-0.5 truncate text-[11px] text-slate-500">
                {label || "Hoy"}
              </p>
            </button>
          );
        })}
      </div>
    </section>
  );
};

const AccountRoomView = ({
  tasks,
  managers,
  clients,
  currentUserProfile,
  onAdd,
  onEdit,
  onChangeStatus,
  onMoveTask,
  onDelete,
  onTaskClick,
  onAttachFiles,
  legacyColorMap,
  onLoadHistory,
  historyLoaded,
  historyLoading,
}) => {
  const {
    currentDate,
    setCurrentDate,
    filterMode,
    setFilterMode,
    ownershipFilter,
    setOwnershipFilter,
    rangeStart,
    setRangeStart,
    rangeEnd,
    setRangeEnd,
  } = useTaskRoomState("cluster_account_room_state", {
    preferMine: Boolean(currentUserProfile?.linkedManagerId),
  });
  const [searchTerm, setSearchTerm] = useState("");
  const [draggedTaskId, setDraggedTaskId] = useState(null);
  const todayStr = getHondurasTodayStr();
  const currentMonthPeriod = getRankingMonthPeriod(todayStr);

  const columns = [
    {
      id: "por_disenar",
      title: "Por Diseñar",
      color: "slate",
      icon: "PenTool",
    },
    {
      id: "aprobacion_interna",
      title: "Aprobación Interna",
      color: "blue",
      icon: "Search",
    },
    {
      id: "aprobado_internamente",
      title: "Aprobado Interno",
      color: "emerald",
      icon: "CheckCircle2",
    },
    { id: "publicado", title: "Publicado", color: "indigo", icon: "Sparkles" },
  ];

  const effectiveRangeStart = rangeStart || todayStr;
  const effectiveRangeEnd = rangeEnd || todayStr;
  const filteredTasks = tasks.filter((t) => {
    if (searchTerm && !t.title.toLowerCase().includes(searchTerm.toLowerCase()))
      return false;
    if (
      ownershipFilter === "mine" &&
      !isTaskAssignedToProfile(t, currentUserProfile, [
        currentUserProfile?.linkedManagerId,
      ])
    )
      return false;
    if (filterMode === "date") return taskMatchesSelectedDay(t, currentDate);
    if (filterMode === "overdue") return taskIsOverdue(t, todayStr, ["publicado"]);
    if (filterMode === "range")
      return taskDueDates(t).some(
        (date) =>
          compareDateOnlyStrings(date, effectiveRangeStart) >= 0 &&
          compareDateOnlyStrings(date, effectiveRangeEnd) <= 0,
      );
    if (filterMode === "history") return true;
    return taskInWorkingBoard(t, currentMonthPeriod, todayStr);
  });
  const canReorder = userHasPermission(currentUserProfile, "manage_account_tasks");
  const tasksForStatus = (statusId) => sortKanbanColumnTasks(
    filteredTasks.filter((task) => task.status === statusId),
  );
  const handleAddTask = (dateStr) => {
    const nextDate = normalizeDateOnlyString(dateStr) || todayStr;
    setCurrentDate(nextDate);
    onAdd(nextDate);
  };

  const handleDragStart = (e, taskId) => {
    setDraggedTaskId(taskId);
    e.dataTransfer.effectAllowed = "move";
    try {
      const rect = e.currentTarget.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const clone = e.currentTarget.cloneNode(true);
      clone.id = "custom-drag-ghost-" + taskId;
      clone.style.width = `${rect.width}px`;
      clone.style.height = `${rect.height}px`;
      clone.style.position = "absolute";
      clone.style.top = "-9999px";
      clone.style.left = "-9999px";
      clone.style.opacity = "1";
      clone.style.backgroundColor = getComputedStyle(
        document.documentElement,
      ).getPropertyValue("--surface-raised");
      clone.style.borderRadius = "0.75rem";
      clone.style.boxShadow = "0 25px 50px -12px rgba(0, 0, 0, 0.4)";
      clone.style.transform = "rotate(3deg) scale(1.05)";
      clone.style.zIndex = "99999";
      clone.style.pointerEvents = "none";
      document.body.appendChild(clone);
      e.dataTransfer.setDragImage(clone, x, y);
    } catch (err) {}
    setTimeout(() => e.currentTarget.classList.add("drag-source-hidden"), 0);
  };

  const handleDragEnd = (e, taskId) => {
    e.currentTarget.classList.remove("drag-source-hidden");
    setDraggedTaskId(null);
    document
      .querySelectorAll(".drag-over")
      .forEach((el) => el.classList.remove("drag-over"));
    const clone = document.getElementById("custom-drag-ghost-" + taskId);
    if (clone) clone.remove();
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.currentTarget.classList.add("drag-over");
  };
  const handleDragLeave = (e) => {
    e.currentTarget.classList.remove("drag-over");
  };
  const handleDrop = (e, targetStatus) => {
    e.preventDefault();
    e.currentTarget.classList.remove("drag-over");
    if (!canReorder || !draggedTaskId) return;
    const task = tasks.find((item) => item.id === draggedTaskId);
    if (task) onMoveTask?.("accountTask", task, targetStatus);
  };
  const handleCardDrop = (targetTask, targetStatus) => {
    if (!canReorder || !draggedTaskId || !targetTask?.id || draggedTaskId === targetTask.id) return;
    const task = tasks.find((item) => item.id === draggedTaskId);
    if (task) onMoveTask?.("accountTask", task, targetStatus, targetTask.id);
  };

  const defaultAddDate =
    filterMode === "date"
      ? currentDate
      : filterMode === "range"
        ? effectiveRangeStart
        : todayStr;
  const accountGroups = columns.map((column) => ({
    id: column.id,
    title: column.title,
    subtitle: {
      por_disenar: "Tareas pendientes de comenzar",
      aprobacion_interna: "Pendientes de aprobación",
      aprobado_internamente: "Aprobadas, listas para publicar",
      publicado: "Ya publicadas",
    }[column.id] || "",
    color: column.color,
    stages: [{
      ...column,
      tasks: tasksForStatus(column.id),
      collapsible: column.id === "publicado",
      collapsedLimit: 3,
    }],
  }));

  const renderAccountTask = (task, stage) => {
    const columnIndex = columns.findIndex((column) => column.id === stage.id);
    const previous = columns[columnIndex - 1];
    const next = columns[columnIndex + 1];
    const manager = managers.find((item) => item.id === task.contextId);
    const client = clients.find((item) => item.id === task.clientId);
    const isOverdue =
      isDateBeforeDateString(task.date, todayStr) && stage.id !== "publicado";
    const menuItems = [];
    if (next)
      menuItems.push({
        key: "next",
        label: next.id === "publicado" ? "Publicar" : `Avanzar a ${next.title}`,
        icon: next.id === "publicado" ? "CheckCircle2" : "ArrowRight",
        onClick: () => onChangeStatus(task, next.id),
      });
    if (previous)
      menuItems.push({
        key: "prev",
        label: `Volver a ${previous.title}`,
        icon: "ChevronLeft",
        onClick: () => onChangeStatus(task, previous.id),
      });
    menuItems.push(
      { key: "edit", label: "Editar", icon: "Edit", onClick: () => onEdit(task) },
      { key: "delete", label: "Eliminar", icon: "Trash2", danger: true, onClick: () => onDelete(task.id) },
    );

    return (
      <KanbanCard
        key={task.id}
        onClick={() => onTaskClick(task)}
        onDropFiles={onAttachFiles ? (files) => onAttachFiles(task, files) : undefined}
        draggable={canReorder}
        onCardDragOver={canReorder ? () => {} : undefined}
        onCardDrop={canReorder ? () => handleCardDrop(task, task.status) : undefined}
        onDragStart={(event) => handleDragStart(event, task.id)}
        onDragEnd={(event) => handleDragEnd(event, task.id)}
        accentTone={stage.color}
        isOverdue={isOverdue}
        client={client?.name}
        title={task.title}
        badges={[
          ...(task.priority
            ? [{
                label: task.priority,
                tone: task.priority === "urgente" ? "red" : task.priority === "recurrente" ? "emerald" : "amber",
              }]
            : []),
          ...(isRecurringTask(task)
            ? [{
                label: getRecurrenceMeta(task.recurrence?.frequency).label,
                tone: "emerald",
              }]
            : []),
        ]}
        due={{
          label: formatShortDate(task.date, task.time) + (isOverdue ? " · atrasada" : ""),
          tone: isOverdue ? "red" : "slate",
        }}
        assignee={buildAssignee(manager, legacyColorMap)}
        menuItems={menuItems}
        statusControl={{
          value: task.status,
          options: columns,
          onChange: (status) => {
            if (status !== task.status) onChangeStatus(task, status);
          },
        }}
      />
    );
  };

  return (
    <div className="task-room min-h-0 flex flex-col gap-3 fade-in">
      <DateHeader
        currentDate={currentDate}
        setCurrentDate={setCurrentDate}
        filterMode={filterMode}
        setFilterMode={setFilterMode}
        ownershipFilter={ownershipFilter}
        setOwnershipFilter={setOwnershipFilter}
        title="Sala de Accounts"
        onAdd={handleAddTask}
        btnColor="indigo"
        btnIcon="Briefcase"
        searchTerm={searchTerm}
        setSearchTerm={setSearchTerm}
        rangeStart={rangeStart}
        setRangeStart={setRangeStart}
        rangeEnd={rangeEnd}
        setRangeEnd={setRangeEnd}
        onLoadHistory={onLoadHistory}
        historyLoaded={historyLoaded}
        historyLoading={historyLoading}
        taskCount={filteredTasks.length}
      />
      <MyDayStrip
        tasks={tasks}
        profile={currentUserProfile}
        clients={clients}
        today={todayStr}
        onOpen={onTaskClick}
        doneStatuses={["publicado", "aprobado_internamente"]}
        linkedIds={[currentUserProfile?.linkedManagerId, currentUserProfile?.id]}
      />
      <TaskRoomWorkspace
        groups={accountGroups}
        onAdd={() => handleAddTask(defaultAddDate)}
        renderTask={renderAccountTask}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      />
    </div>
  );
};

const EditionsRoomView = ({
  tasks,
  editors,
  clients,
  currentUserProfile,
  onAdd,
  onEdit,
  onChangeStatus,
  onMoveTask,
  onDelete,
  onTaskClick,
  onAttachFiles,
  onLoadHistory,
  historyLoaded,
  historyLoading,
}) => {
  const {
    currentDate,
    setCurrentDate,
    filterMode,
    setFilterMode,
    ownershipFilter,
    setOwnershipFilter,
  } = useTaskRoomState("cluster_editions_room_state", {
    preferMine: Boolean(currentUserProfile?.linkedEditorId),
  });
  const [searchTerm, setSearchTerm] = useState("");
  const [draggedTaskId, setDraggedTaskId] = useState(null);
  const todayStr = getHondurasTodayStr();
  const currentMonthPeriod = getRankingMonthPeriod(todayStr);

  const columns = [
    { id: "editar", title: "Por Editar", color: "slate", icon: "PenTool" },
    { id: "en_edicion", title: "En Edición", color: "amber", icon: "Video" },
    {
      id: "revision_interna",
      title: "En Revisión",
      color: "blue",
      icon: "Search",
    },
    {
      id: "aprobado",
      title: "Aprobado",
      color: "emerald",
      icon: "CheckCircle2",
    },
    { id: "publicado", title: "Publicado", color: "indigo", icon: "Sparkles" },
  ];

  const priorityStyles = {
    urgente:
      "bg-red-50 dark:bg-red-500/20 border-red-200 dark:border-red-500/30 text-red-700 dark:text-red-400",
    normal:
      "bg-amber-50 dark:bg-amber-500/20 border-amber-200 dark:border-amber-500/30 text-amber-700 dark:text-amber-400",
    recurrente:
      "bg-emerald-50 dark:bg-emerald-500/20 border-emerald-200 dark:border-emerald-500/30 text-emerald-700 dark:text-emerald-400",
  };
  const hierarchyStyles = {
    p1: "bg-red-50 dark:bg-red-500/20 border-red-200 dark:border-red-500/30 text-red-700 dark:text-red-400",
    p2: "bg-amber-50 dark:bg-amber-500/20 border-amber-200 dark:border-amber-500/30 text-amber-700 dark:text-amber-400",
    p3: "bg-emerald-50 dark:bg-emerald-500/20 border-emerald-200 dark:border-emerald-500/30 text-emerald-700 dark:text-emerald-400",
    p4: "bg-slate-100 dark:bg-slate-700 border-slate-200 dark:border-slate-600 text-slate-600 dark:text-slate-300",
  };

  const filteredTasks = tasks.filter((t) => {
    if (searchTerm && !t.title.toLowerCase().includes(searchTerm.toLowerCase()))
      return false;
    if (
      ownershipFilter === "mine" &&
      !isTaskAssignedToProfile(t, currentUserProfile, [
        currentUserProfile?.linkedEditorId,
      ])
    )
      return false;
    if (filterMode === "date") return taskMatchesSelectedDay(t, currentDate);
    if (filterMode === "overdue") return taskIsOverdue(t, todayStr, ["publicado"]);
    if (filterMode === "history") return true;
    return taskInWorkingBoard(t, currentMonthPeriod, todayStr);
  });
  const canManageEditingTasks = userHasPermission(
    currentUserProfile,
    "manage_editing_tasks",
  );
  const canCreateEditingTasks = userHasPermission(
    currentUserProfile,
    "create_editing_tasks",
  );
  const handleAddTask = (dateStr) => {
    const nextDate = normalizeDateOnlyString(dateStr) || todayStr;
    setCurrentDate(nextDate);
    onAdd(nextDate);
  };
  const rankedTasks = rankPendingEditingTasks(filteredTasks, todayStr);
  const displayTasks = [
    ...rankedTasks,
    ...filteredTasks.filter((task) => !isEditingActionable(task)),
  ];
  const rankingMap = rankedTasks.reduce(
    (acc, task, index) => ({ ...acc, [task.id]: index + 1 }),
    {},
  );
  const canReorder = userHasPermission(currentUserProfile, "manage_editing_tasks");
  const tasksForStatus = (statusId) =>
    sortKanbanColumnTasks(
      displayTasks.filter(
        (task) => normalizeEditingWorkflowStatus(task.status) === statusId,
      ),
    );
  const columnRankMap = columns.reduce((acc, column) => {
    tasksForStatus(column.id).forEach((task, index) => {
      acc[task.id] = index + 1;
    });
    return acc;
  }, {});

  const handleDragStart = (e, taskId) => {
    setDraggedTaskId(taskId);
    e.dataTransfer.effectAllowed = "move";
    try {
      const rect = e.currentTarget.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const clone = e.currentTarget.cloneNode(true);
      clone.id = "custom-drag-ghost-edit-" + taskId;
      clone.style.width = `${rect.width}px`;
      clone.style.height = `${rect.height}px`;
      clone.style.position = "absolute";
      clone.style.top = "-9999px";
      clone.style.left = "-9999px";
      clone.style.opacity = "1";
      clone.style.backgroundColor = getComputedStyle(
        document.documentElement,
      ).getPropertyValue("--surface-raised");
      clone.style.borderRadius = "0.75rem";
      clone.style.boxShadow = "0 25px 50px -12px rgba(0, 0, 0, 0.4)";
      clone.style.transform = "rotate(3deg) scale(1.05)";
      clone.style.zIndex = "99999";
      clone.style.pointerEvents = "none";
      document.body.appendChild(clone);
      e.dataTransfer.setDragImage(clone, x, y);
    } catch (err) {}
    setTimeout(() => e.currentTarget.classList.add("drag-source-hidden"), 0);
  };

  const handleDragEnd = (e, taskId) => {
    e.currentTarget.classList.remove("drag-source-hidden");
    setDraggedTaskId(null);
    document
      .querySelectorAll(".drag-over")
      .forEach((el) => el.classList.remove("drag-over"));
    const clone = document.getElementById("custom-drag-ghost-edit-" + taskId);
    if (clone) clone.remove();
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.currentTarget.classList.add("drag-over");
  };
  const handleDragLeave = (e) => {
    e.currentTarget.classList.remove("drag-over");
  };
  const handleDrop = (e, targetStatus) => {
    e.preventDefault();
    e.currentTarget.classList.remove("drag-over");
    if (!canReorder || !draggedTaskId) return;
    const task = tasks.find((t) => t.id === draggedTaskId);
    if (!task) return;
    onMoveTask?.("editingTask", task, targetStatus);
  };
  const handleCardDrop = (targetTask, targetStatus) => {
    if (!canReorder || !draggedTaskId || !targetTask?.id || draggedTaskId === targetTask.id) return;
    const task = tasks.find((t) => t.id === draggedTaskId);
    if (!task) return;
    onMoveTask?.("editingTask", task, targetStatus, targetTask.id);
  };

  const defaultAddDate = filterMode === "date" ? currentDate : todayStr;
  const editingGroups = [
    {
      id: "start",
      title: "Por iniciar",
      subtitle: "Tareas pendientes de comenzar",
      color: "slate",
      stages: [{
        ...columns[0],
        tasks: tasksForStatus(columns[0].id),
      }],
    },
    {
      id: "production",
      title: "En producción",
      subtitle: "En edición",
      color: "amber",
      stages: [{
        ...columns[1],
        tasks: tasksForStatus(columns[1].id),
      }],
    },
    {
      id: "review",
      title: "En revisión",
      subtitle: "Pendientes de aprobación",
      color: "blue",
      stages: [{
        ...columns[2],
        tasks: tasksForStatus(columns[2].id),
      }],
    },
    {
      id: "ready",
      title: "Listas",
      subtitle: "Aprobadas y publicadas",
      color: "emerald",
      stages: columns.slice(3).map((column) => ({
        ...column,
        tasks: tasksForStatus(column.id),
        collapsible: column.id === "publicado",
        collapsedLimit: 3,
      })),
    },
  ];

  const renderEditingTask = (task, stage) => {
    const columnIndex = columns.findIndex((column) => column.id === stage.id);
    const previous = columns[columnIndex - 1];
    const next = columns[columnIndex + 1];
    const editor = editors.find((item) => item.id === task.contextId);
    const client = clients.find((item) => item.id === task.clientId);
    const isOverdue =
      isDateBeforeDateString(task.date, todayStr) && !isCompletedStatus(task.status);
    const hierarchyId = task.hierarchy || getEditingHierarchyId(task);
    const hierarchyTone =
      hierarchyId === "p1"
        ? "red"
        : hierarchyId === "p2"
          ? "amber"
          : hierarchyId === "p3"
            ? "emerald"
            : "slate";
    const priorityTone =
      task.priority === "urgente"
        ? "red"
        : task.priority === "recurrente"
          ? "emerald"
          : "amber";
    const menuItems = [];
    if (canManageEditingTasks) {
      if (next)
        menuItems.push({
          key: "next",
          label: next.id === "publicado" ? "Publicar" : `Avanzar a ${next.title}`,
          icon: next.id === "publicado" ? "CheckCircle2" : "ArrowRight",
          onClick: () => onChangeStatus(task, next.id),
        });
      if (previous)
        menuItems.push({
          key: "prev",
          label: `Volver a ${previous.title}`,
          icon: "ChevronLeft",
          onClick: () => onChangeStatus(task, previous.id),
        });
      menuItems.push(
        { key: "edit", label: "Editar", icon: "Edit", onClick: () => onEdit(task) },
        { key: "delete", label: "Eliminar", icon: "Trash2", danger: true, onClick: () => onDelete(task.id) },
      );
    }

    return (
      <KanbanCard
        key={task.id}
        onClick={() => onTaskClick(task)}
        onDropFiles={
          canManageEditingTasks && onAttachFiles
            ? (files) => onAttachFiles(task, files)
            : undefined
        }
        onCardDragOver={canReorder ? () => {} : undefined}
        onCardDrop={
          canReorder
            ? () => handleCardDrop(task, normalizeEditingWorkflowStatus(task.status))
            : undefined
        }
        reorderable={canReorder}
        draggable={canReorder}
        onDragStart={(event) => handleDragStart(event, task.id)}
        onDragEnd={(event) => handleDragEnd(event, task.id)}
        accentTone={hierarchyTone}
        isOverdue={isOverdue}
        client={client?.name}
        rank={columnRankMap[task.id] || rankingMap[task.id]}
        title={task.title}
        notes={task.notes}
        badges={[
          { label: hierarchyId.toUpperCase(), tone: hierarchyTone },
          { label: task.priority || "Normal", tone: priorityTone },
          ...(isRecurringTask(task)
            ? [{
                label: getRecurrenceMeta(task.recurrence?.frequency).label,
                tone: "emerald",
              }]
            : []),
        ]}
        due={{
          label: formatShortDate(task.date, task.time) + (isOverdue ? " · atrasada" : ""),
          tone: isOverdue ? "red" : "slate",
        }}
        assignee={buildAssignee(editor)}
        menuItems={menuItems}
        statusControl={
          canManageEditingTasks
            ? {
                value: normalizeEditingWorkflowStatus(task.status),
                options: columns,
                onChange: (status) => {
                  if (status !== normalizeEditingWorkflowStatus(task.status))
                    onChangeStatus(task, status);
                },
              }
            : null
        }
      />
    );
  };

  return (
    <div className="task-room min-h-0 flex flex-col gap-3 fade-in">
      <DateHeader
        currentDate={currentDate}
        setCurrentDate={setCurrentDate}
        filterMode={filterMode}
        setFilterMode={setFilterMode}
        ownershipFilter={ownershipFilter}
        setOwnershipFilter={setOwnershipFilter}
        title="Sala de Edición"
        onAdd={handleAddTask}
        btnColor="amber"
        btnIcon="Video"
        searchTerm={searchTerm}
        setSearchTerm={setSearchTerm}
        onLoadHistory={onLoadHistory}
        historyLoaded={historyLoaded}
        historyLoading={historyLoading}
        taskCount={filteredTasks.length}
      />
      <MyDayStrip
        tasks={tasks}
        profile={currentUserProfile}
        clients={clients}
        today={todayStr}
        onOpen={onTaskClick}
        doneStatuses={["aprobado", "publicado"]}
        linkedIds={[currentUserProfile?.linkedEditorId, currentUserProfile?.id]}
      />
      <TaskRoomWorkspace
        groups={editingGroups}
        onAdd={() => handleAddTask(defaultAddDate)}
        canAdd={canCreateEditingTasks}
        renderTask={renderEditingTask}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      />
    </div>
  );
};

const computeManagementDueBadge = (task) => {
  if (!task?.date || !task?.time || !/^\d{2}:\d{2}$/.test(task.time))
    return null;
  const ms = parseBusinessDueMs(task.date, task.time);
  if (!Number.isFinite(ms)) return null;
  const diffMs = ms - Date.now();
  const absHours = Math.abs(diffMs) / 3600000;
  if (diffMs >= 0) {
    if (absHours >= 48)
      return { label: `Vence en ${Math.round(absHours / 24)}d`, tone: "slate" };
    if (absHours >= 1)
      return {
        label: `Vence en ${Math.round(absHours)}h`,
        tone: absHours <= 8 ? "amber" : "slate",
      };
    const mins = Math.max(1, Math.round(diffMs / 60000));
    return { label: `Vence en ${mins}m`, tone: "red" };
  }
  if (absHours < 1)
    return {
      label: `Vencida hace ${Math.max(1, Math.round(-diffMs / 60000))}m`,
      tone: "red",
    };
  if (absHours < 48)
    return { label: `Vencida hace ${Math.round(absHours)}h`, tone: "red" };
  return { label: `Vencida hace ${Math.round(absHours / 24)}d`, tone: "red" };
};

