const downloadAuthenticatedPdf = async (path, fallbackName) => {
  const response = await fetch(buildApiUrl(path), { credentials: "include" });
  if (!response.ok) {
    throw new Error("No se pudo generar el PDF");
  }
  const blob = await response.blob();
  const disposition = response.headers.get("Content-Disposition") || "";
  const match = disposition.match(/filename="([^"]+)"/);
  const objectUrl = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = objectUrl;
  link.download = match?.[1] || fallbackName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(objectUrl);
};

const ReportsView = ({
  accountTasks,
  editingTasks,
  managementTasks,
  clients,
  managers,
  editors,
  users = [],
  onRefresh,
  refreshing = false,
  onOpenDailyReport,
  periodPreset = "custom",
  expandAllSections = false,
}) => {
  const todayStr = getHondurasTodayStr();
  const now = new Date();
  const firstOfMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-01`;
  const initialLast24h = periodPreset === "last24h" ? getLast24HoursRange() : null;
  const [fromDate, setFromDate] = useState(initialLast24h?.fromDate || firstOfMonth);
  const [toDate, setToDate] = useState(initialLast24h?.toDate || todayStr);
  const [activeTab, setActiveTab] = useState("content");

  useEffect(() => {
    if (periodPreset !== "last24h") return undefined;
    const range = getLast24HoursRange();
    setFromDate(range.fromDate);
    setToDate(range.toDate);
    return undefined;
  }, [periodPreset]);
  const [downloadingPdf, setDownloadingPdf] = useState("");
  const [pdfError, setPdfError] = useState("");
  const hasAutoExpandedRangeRef = useRef(false);

  const inRange = (dateStr) => {
    if (!dateStr) return false;
    return (
      compareDateOnlyStrings(dateStr, fromDate) >= 0 &&
      compareDateOnlyStrings(dateStr, toDate) <= 0
    );
  };

  const filteredAccountTasks = accountTasks.filter((t) => inRange(t.date));
  const filteredEditingTasks = editingTasks.filter((t) => inRange(t.date));
  const filteredManagementTasks = managementTasks.filter((t) =>
    inRange(t.date),
  );

  useEffect(() => {
    if (hasAutoExpandedRangeRef.current) return;
    const allTaskDates = [...accountTasks, ...editingTasks, ...managementTasks]
      .map((task) => normalizeDateOnlyString(task.date))
      .filter(Boolean)
      .sort();
    if (allTaskDates.length === 0) return;
    const hasCurrentRangeData = allTaskDates.some(inRange);
    if (hasCurrentRangeData) {
      hasAutoExpandedRangeRef.current = true;
      return;
    }
    setFromDate(allTaskDates[0]);
    setToDate(todayStr);
    hasAutoExpandedRangeRef.current = true;
  }, [accountTasks, editingTasks, managementTasks]);

  const managerById = new Map(managers.map((item) => [item.id, item]));
  const editorById = new Map(editors.map((item) => [item.id, item]));
  const userById = new Map(users.map((item) => [item.id, item]));
  const userByManagerId = new Map(
    users
      .filter((item) => item.linkedManagerId)
      .map((item) => [item.linkedManagerId, item]),
  );
  const userByEditorId = new Map(
    users
      .filter((item) => item.linkedEditorId)
      .map((item) => [item.linkedEditorId, item]),
  );
  const performancePeopleByKey = new Map();
  const roleLabelByKey = {
    super_admin: "Admin",
    operations: "Operaciones",
    management: "Gestion",
    manager: "Manager",
    editor: "Editor",
    viewer: "Viewer",
  };
  const addPerformancePerson = (key, data = {}) => {
    if (!key) return null;
    const current = performancePeopleByKey.get(key) || {
      id: key,
      name: "",
      email: "",
      roles: [],
    };
    const roles = [...current.roles];
    if (data.roleLabel && !roles.includes(data.roleLabel))
      roles.push(data.roleLabel);
    const nextPerson = {
      id: key,
      name: current.name || data.name || data.email || "Usuario sin nombre",
      email: current.email || data.email || "",
      roles,
      managerId: current.managerId || data.managerId || "",
      editorId: current.editorId || data.editorId || "",
    };
    performancePeopleByKey.set(key, nextPerson);
    return nextPerson;
  };
  users.forEach((item) =>
    addPerformancePerson(item.id, {
      name: item.name,
      email: item.email,
      roleLabel: roleLabelByKey[item.role] || item.role || "Usuario",
      managerId: item.linkedManagerId || "",
      editorId: item.linkedEditorId || "",
    }),
  );
  managers.forEach((item) => {
    const linkedUser =
      userByManagerId.get(item.id) ||
      (item.userId ? userById.get(item.userId) : null);
    addPerformancePerson(linkedUser?.id || item.userId || item.id, {
      name: item.name || linkedUser?.name,
      email: item.email || linkedUser?.email,
      roleLabel: "Manager",
      managerId: item.id,
    });
  });
  editors.forEach((item) => {
    const linkedUser =
      userByEditorId.get(item.id) ||
      (item.userId ? userById.get(item.userId) : null);
    addPerformancePerson(linkedUser?.id || item.userId || item.id, {
      name: item.name || linkedUser?.name,
      email: item.email || linkedUser?.email,
      roleLabel: "Editor",
      editorId: item.id,
    });
  });
  const resolveManagerPerformanceKey = (managerId = "", directUserId = "") => {
    const manager =
      managerById.get(managerId) ||
      (directUserId
        ? managers.find((item) => item.userId === directUserId)
        : null);
    const linkedUser = manager
      ? userByManagerId.get(manager.id) ||
        (manager.userId ? userById.get(manager.userId) : null)
      : null;
    const directUser = directUserId ? userById.get(directUserId) : null;
    const key =
      directUser?.id ||
      directUserId ||
      linkedUser?.id ||
      manager?.userId ||
      manager?.id ||
      managerId;
    addPerformancePerson(key, {
      name: manager?.name || directUser?.name || linkedUser?.name,
      email: manager?.email || directUser?.email || linkedUser?.email,
      roleLabel: "Manager",
      managerId: manager?.id || managerId,
    });
    return key;
  };
  const resolveEditorPerformanceKey = (editorId = "", directUserId = "") => {
    const editor =
      editorById.get(editorId) ||
      (directUserId
        ? editors.find((item) => item.userId === directUserId)
        : null);
    const linkedUser = editor
      ? userByEditorId.get(editor.id) ||
        (editor.userId ? userById.get(editor.userId) : null)
      : null;
    const directUser = directUserId ? userById.get(directUserId) : null;
    const key =
      directUser?.id ||
      directUserId ||
      linkedUser?.id ||
      editor?.userId ||
      editor?.id ||
      editorId;
    addPerformancePerson(key, {
      name: editor?.name || directUser?.name || linkedUser?.name,
      email: editor?.email || directUser?.email || linkedUser?.email,
      roleLabel: "Editor",
      editorId: editor?.id || editorId,
    });
    return key;
  };
  const resolveManagementPerformanceKey = (userId = "") => {
    const record = userById.get(userId);
    const key = record?.id || userId;
    addPerformancePerson(key, {
      name: record?.name,
      email: record?.email,
      roleLabel: roleLabelByKey[record?.role] || "Gestion",
      managerId: record?.linkedManagerId || "",
      editorId: record?.linkedEditorId || "",
    });
    return key;
  };
  const getTaskAssigneeKeys = (task, type) => {
    const storedAssignees =
      type === "editing" &&
      isEditingDelivered(task) &&
      Array.isArray(task.editorAssigneesAtCompletion)
        ? task.editorAssigneesAtCompletion
        : task.assignees;
    const explicitAssignees = Array.isArray(storedAssignees)
      ? storedAssignees.filter(Boolean)
      : [];
    const keys = new Set();
    if (type === "account")
      explicitAssignees.forEach((id) =>
        keys.add(resolveManagerPerformanceKey(id, "")),
      );
    if (type === "editing")
      explicitAssignees.forEach((id) =>
        keys.add(resolveEditorPerformanceKey(id, "")),
      );
    if (type === "management")
      explicitAssignees.forEach((id) =>
        keys.add(resolveManagementPerformanceKey(id)),
      );
    if (keys.size === 0 && type === "account")
      keys.add(
        resolveManagerPerformanceKey(task.contextId, task.assigneeUserId),
      );
    if (keys.size === 0 && type === "editing")
      keys.add(
        resolveEditorPerformanceKey(
          task.editorOwnerAtCompletionId || task.contextId,
          task.editorAssigneeUserAtCompletionId || task.assigneeUserId,
        ),
      );
    if (keys.size === 0 && type === "management")
      keys.add(
        resolveManagementPerformanceKey(task.assigneeUserId || task.contextId),
      );
    return [...keys].filter(Boolean);
  };
  const dailyPerformanceByKey = new Map();
  const taskCreatedDay = (task) =>
    getHondurasDateFromIso(task.createdAt) ||
    normalizeDateOnlyString(task.date);
  const addDailyPerformanceTask = (task, type) => {
    const createdDate = taskCreatedDay(task);
    if (!createdDate || !inRange(createdDate)) return;
    const areaKey =
      type === "account"
        ? "account"
        : type === "editing"
          ? "editing"
          : "management";
    const isDoneStatus =
      type === "account"
        ? ["publicado", "aprobado_internamente"].includes(task.status)
        : type === "editing"
          ? isEditingDelivered(task)
          : task.status === "cerrado";
    const completionIso =
      getMeasuredCompletionIso(task) ||
      (isDoneStatus ? task.updatedAt || task.createdAt || "" : "");
    const completedDate = isDoneStatus
      ? getHondurasDateFromIso(completionIso) || createdDate
      : "";
    const sameDayDone = Boolean(
      isDoneStatus && completedDate && completedDate === createdDate,
    );
    getTaskAssigneeKeys(task, type).forEach((personKey) => {
      const person =
        performancePeopleByKey.get(personKey) ||
        addPerformancePerson(personKey, {});
      const rowKey = `${createdDate}:${person.id}`;
      const current = dailyPerformanceByKey.get(rowKey) || {
        date: createdDate,
        userId: person.id,
        name: person.name,
        email: person.email,
        roles: person.roles,
        total: 0,
        done: 0,
        pending: 0,
        areas: { account: 0, editing: 0, management: 0 },
      };
      current.name = person.name || current.name;
      current.email = person.email || current.email;
      current.roles = person.roles;
      current.total += 1;
      current.done += sameDayDone ? 1 : 0;
      current.pending += sameDayDone ? 0 : 1;
      current.areas[areaKey] += 1;
      dailyPerformanceByKey.set(rowKey, current);
    });
  };
  accountTasks.forEach((task) => addDailyPerformanceTask(task, "account"));
  editingTasks.forEach((task) => addDailyPerformanceTask(task, "editing"));
  managementTasks.forEach((task) => addDailyPerformanceTask(task, "management"));
  const dailyPerformanceStats = [...dailyPerformanceByKey.values()].sort(
    (left, right) =>
      compareDateOnlyStrings(right.date, left.date) ||
      right.total - left.total ||
      left.name.localeCompare(right.name),
  );
  const dailyPerformanceTotals = dailyPerformanceStats.reduce(
    (acc, row) => ({
      total: acc.total + row.total,
      done: acc.done + row.done,
      pending: acc.pending + row.pending,
    }),
    { total: 0, done: 0, pending: 0 },
  );
  const dailyUserCount = new Set(dailyPerformanceStats.map((row) => row.userId))
    .size;
  const dailyDateCount = new Set(dailyPerformanceStats.map((row) => row.date))
    .size;

  const downloadDailyPdf = async (scope) => {
    const report = PERFORMANCE_REPORT_PDFS.find((item) => item.id === scope);
    if (!report || downloadingPdf) return;
    setPdfError("");
    setDownloadingPdf(scope);
    try {
      await downloadAuthenticatedPdf(report.path, report.file);
    } catch (error) {
      setPdfError(error.message || "No se pudo generar el PDF");
    } finally {
      setDownloadingPdf("");
    }
  };

  const accountPublished = filteredAccountTasks.filter(
    (t) => t.status === "publicado",
  ).length;
  const editingPublished = filteredEditingTasks.filter(
    (t) => t.status === "publicado",
  ).length;
  const totalContentPieces =
    filteredAccountTasks.length + filteredEditingTasks.length;
  const totalPublished = accountPublished + editingPublished;

  const managerStats = managers
    .map((m) => {
      const mTasks = filteredAccountTasks.filter((t) => t.contextId === m.id);
      return {
        ...m,
        total: mTasks.length,
        published: mTasks.filter((t) => t.status === "publicado").length,
        approved: mTasks.filter((t) => t.status === "aprobado_internamente")
          .length,
        inProgress: mTasks.filter(
          (t) => !["publicado", "aprobado_internamente"].includes(t.status),
        ).length,
      };
    })
    .filter((m) => m.total > 0)
    .sort((a, b) => b.total - a.total);

  const editorStats = editors
    .map((e) => {
      const eTasks = filteredEditingTasks.filter((t) => t.contextId === e.id);
      return {
        ...e,
        total: eTasks.length,
        published: eTasks.filter((t) => t.status === "publicado").length,
        approved: eTasks.filter((t) => t.status === "aprobado").length,
        inProgress: eTasks.filter(
          (t) => !["publicado", "aprobado"].includes(t.status),
        ).length,
      };
    })
    .filter((e) => e.total > 0)
    .sort((a, b) => b.total - a.total);

  const tabs = [
    { id: "content", label: "Piezas de Contenido" },
    { id: "daily", label: "Diario por Usuario" },
    { id: "managers", label: "Por Manager" },
    { id: "editors", label: "Por Editor" },
    { id: "management", label: "Gestión" },
  ];
  const showSection = (id) => expandAllSections || activeTab === id;

  const rowStyle = (i) =>
    i % 2 !== 0 ? "bg-slate-50/50 dark:bg-slate-950/30" : "";

  return (
    <div className={`space-y-6 fade-in ${expandAllSections ? "is-capturing-reports" : ""}`}>
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div>
        <h2 className="text-2xl font-black text-slate-800 dark:text-white">
          Reportes
        </h2>
          {expandAllSections && (
            <p className="mt-1 text-sm font-semibold text-slate-500 dark:text-slate-400">
              Informe completo · {fromDate} → {toDate}
            </p>
          )}
        </div>
        {!expandAllSections && (
        <div className="flex items-center gap-3 flex-wrap">
          <div className="flex items-center gap-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-4 py-2.5">
            <span className="text-xs font-black text-slate-500 uppercase">
              Desde
            </span>
            <input
              type="date"
              value={fromDate}
              onChange={(e) => setFromDate(e.target.value)}
              className="text-sm font-bold text-slate-700 dark:text-slate-200 bg-transparent outline-none"
            />
          </div>
          <div className="flex items-center gap-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-4 py-2.5">
            <span className="text-xs font-black text-slate-500 uppercase">
              Hasta
            </span>
            <input
              type="date"
              value={toDate}
              onChange={(e) => setToDate(e.target.value)}
              className="text-sm font-bold text-slate-700 dark:text-slate-200 bg-transparent outline-none"
            />
          </div>
          <button
            type="button"
            onClick={() => downloadDailyPdf("general")}
            disabled={Boolean(downloadingPdf)}
            className="flex min-h-11 items-center gap-2 rounded-xl bg-slate-900 px-4 py-2 text-xs font-black text-white disabled:opacity-40 dark:bg-white dark:text-slate-900"
          >
            <Icon
              name={downloadingPdf === "general" ? "Loader2" : "FileText"}
              size={14}
              className={downloadingPdf === "general" ? "animate-spin" : ""}
            />
            PDF general
          </button>
          <button
            type="button"
            onClick={() => downloadDailyPdf("editors")}
            disabled={Boolean(downloadingPdf)}
            className="flex min-h-11 items-center gap-2 rounded-xl border border-slate-200 px-4 py-2 text-xs font-black text-slate-700 disabled:opacity-40 dark:border-slate-700 dark:text-slate-200"
          >
            PDF editores
          </button>
          <button
            type="button"
            onClick={() => downloadDailyPdf("managers")}
            disabled={Boolean(downloadingPdf)}
            className="flex min-h-11 items-center gap-2 rounded-xl border border-slate-200 px-4 py-2 text-xs font-black text-slate-700 disabled:opacity-40 dark:border-slate-700 dark:text-slate-200"
          >
            PDF community
          </button>
          {onRefresh && (
            <button
              type="button"
              onClick={onRefresh}
              disabled={refreshing || Boolean(downloadingPdf)}
              className="flex min-h-11 items-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-2 text-xs font-black text-emerald-700 disabled:opacity-40 dark:border-emerald-500/30 dark:bg-emerald-500/10 dark:text-emerald-300"
            >
              <Icon
                name="RefreshCw"
                size={14}
                className={refreshing ? "animate-spin" : ""}
              />
              {refreshing ? "Actualizando..." : "Actualizar"}
            </button>
          )}
          {onOpenDailyReport && (
            <button
              type="button"
              onClick={() => onOpenDailyReport({ capture: true })}
              className="flex min-h-11 items-center gap-2 rounded-xl border border-indigo-200 bg-indigo-50 px-4 py-2 text-xs font-black text-indigo-700 dark:border-indigo-500/30 dark:bg-indigo-500/10 dark:text-indigo-300"
            >
              <Icon name="FileText" size={14} />
              Descargar PDF de Rendimiento
            </button>
          )}
        </div>
        )}
      </div>
      {pdfError ? (
        <p className="text-sm font-semibold text-red-600">{pdfError}</p>
      ) : null}

      <div
        data-daily-capture-section={expandAllSections ? "reports-overview" : undefined}
        className="grid grid-cols-2 md:grid-cols-4 gap-4"
      >
        <ReportStatCard
          label="Total Piezas"
          value={totalContentPieces}
          color="purple"
          icon="BarChart3"
          sub="accounts + edición"
        />
        <ReportStatCard
          label="Publicadas"
          value={totalPublished}
          color="emerald"
          icon="CheckCircle2"
          sub={`${Math.round(totalContentPieces > 0 ? (totalPublished / totalContentPieces) * 100 : 0)}% del total`}
        />
        <ReportStatCard
          label="Sala Accounts"
          value={filteredAccountTasks.length}
          color="indigo"
          icon="LayoutList"
          sub={`${accountPublished} publicadas`}
        />
        <ReportStatCard
          label="Sala Edición"
          value={filteredEditingTasks.length}
          color="amber"
          icon="Video"
          sub={`${editingPublished} publicadas`}
        />
      </div>

      {!expandAllSections && (
      <div className="flex gap-1 border-b border-slate-200 dark:border-slate-800">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`px-4 py-2.5 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${activeTab === tab.id ? "border-purple-500 text-purple-600 dark:text-purple-400" : "border-transparent text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"}`}
          >
            {tab.label}
          </button>
        ))}
      </div>
      )}

      {showSection("content") && (
        <div
          data-daily-capture-section={expandAllSections ? "reports-content" : undefined}
          className="space-y-4"
        >
          {expandAllSections && (
            <h3 className="text-lg font-black text-slate-800 dark:text-white">
              Piezas de contenido
            </h3>
          )}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 p-6">
            <h3 className="font-black text-slate-800 dark:text-white mb-5 flex items-center gap-2">
              <Icon name="LayoutList" size={18} className="text-indigo-500" />{" "}
              Sala de Accounts
            </h3>
            <div className="space-y-3">
              {[
                { label: "Por Diseñar", status: "por_disenar", color: "slate" },
                {
                  label: "Aprobación Interna",
                  status: "aprobacion_interna",
                  color: "blue",
                },
                {
                  label: "Aprobado Internamente",
                  status: "aprobado_internamente",
                  color: "emerald",
                },
                { label: "Publicado", status: "publicado", color: "indigo" },
              ].map((row) => {
                const count = filteredAccountTasks.filter(
                  (t) => t.status === row.status,
                ).length;
                const pct =
                  filteredAccountTasks.length > 0
                    ? Math.round((count / filteredAccountTasks.length) * 100)
                    : 0;
                return (
                  <div key={row.status}>
                    <div className="flex items-center gap-2 mb-1">
                      <span
                        className={`w-2 h-2 rounded-full bg-${row.color}-500 shrink-0`}
                      />
                      <span className="text-sm text-slate-600 dark:text-slate-300 flex-1">
                        {row.label}
                      </span>
                      <span className="font-black text-slate-800 dark:text-white">
                        {count}
                      </span>
                      <span className="text-xs text-slate-500 w-8 text-right">
                        {pct}%
                      </span>
                    </div>
                    <div className="h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                      <div
                        className={`h-full bg-${row.color}-500 rounded-full transition-all duration-500`}
                        style={{ width: `${pct}%` }}
                      />
                    </div>
                  </div>
                );
              })}
              <div className="pt-3 border-t border-slate-100 dark:border-slate-800 flex justify-between">
                <span className="text-sm font-bold text-slate-500">Total</span>
                <span className="font-black text-slate-800 dark:text-white">
                  {filteredAccountTasks.length}
                </span>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 p-6">
            <h3 className="font-black text-slate-800 dark:text-white mb-5 flex items-center gap-2">
              <Icon name="Video" size={18} className="text-amber-500" /> Sala de
              Edición
            </h3>
            <div className="space-y-3">
              {[
                { label: "Por Editar", status: "editar", color: "slate" },
                { label: "En Edición", status: "en_edicion", color: "amber" },
                {
                  label: "Revisión Interna",
                  status: "revision_interna",
                  color: "blue",
                },
                { label: "Aprobado", status: "aprobado", color: "emerald" },
                { label: "Publicado", status: "publicado", color: "indigo" },
              ].map((row) => {
                const count = filteredEditingTasks.filter(
                  (t) => t.status === row.status,
                ).length;
                const pct =
                  filteredEditingTasks.length > 0
                    ? Math.round((count / filteredEditingTasks.length) * 100)
                    : 0;
                return (
                  <div key={row.status}>
                    <div className="flex items-center gap-2 mb-1">
                      <span
                        className={`w-2 h-2 rounded-full bg-${row.color}-500 shrink-0`}
                      />
                      <span className="text-sm text-slate-600 dark:text-slate-300 flex-1">
                        {row.label}
                      </span>
                      <span className="font-black text-slate-800 dark:text-white">
                        {count}
                      </span>
                      <span className="text-xs text-slate-500 w-8 text-right">
                        {pct}%
                      </span>
                    </div>
                    <div className="h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                      <div
                        className={`h-full bg-${row.color}-500 rounded-full transition-all duration-500`}
                        style={{ width: `${pct}%` }}
                      />
                    </div>
                  </div>
                );
              })}
              <div className="pt-3 border-t border-slate-100 dark:border-slate-800 flex justify-between">
                <span className="text-sm font-bold text-slate-500">Total</span>
                <span className="font-black text-slate-800 dark:text-white">
                  {filteredEditingTasks.length}
                </span>
              </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {showSection("daily") && (
        <div
          data-daily-capture-section={expandAllSections ? "reports-daily" : undefined}
          className="space-y-4"
        >
          {expandAllSections && (
            <h3 className="text-lg font-black text-slate-800 dark:text-white">
              Diario por usuario
            </h3>
          )}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <ReportStatCard
              label="Usuarios Activos"
              value={dailyUserCount}
              color="violet"
              icon="Users"
              sub={`${dailyDateCount} dias con actividad`}
            />
            <ReportStatCard
              label="Creadas"
              value={dailyPerformanceTotals.total}
              color="indigo"
              icon="LayoutList"
              sub="creadas en el rango"
            />
            <ReportStatCard
              label="Completadas mismo dia"
              value={dailyPerformanceTotals.done}
              color="emerald"
              icon="CheckCircle2"
              sub={`${Math.round(dailyPerformanceTotals.total > 0 ? (dailyPerformanceTotals.done / dailyPerformanceTotals.total) * 100 : 0)}% de cierre`}
            />
            <ReportStatCard
              label="Pendientes"
              value={dailyPerformanceTotals.pending}
              color="amber"
              icon="Clock"
              sub="abiertas en el rango"
            />
          </div>

          <p className="rounded-xl border border-blue-200 bg-blue-50 px-4 py-3 text-xs font-semibold text-blue-700 dark:border-blue-500/20 dark:bg-blue-500/10 dark:text-blue-300">
            Criterio: tareas creadas ese dia y completadas el mismo dia. En
            Edicion cuenta al pasar a Revision Interna. El PDF automatico usa la
            ventana 6:00 AM a 6:00 AM Honduras.
          </p>

          <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden">
            {dailyPerformanceStats.length === 0 ? (
              <div className="p-16 text-center text-slate-500 font-bold">
                Sin desempeno diario en este rango de fechas
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full min-w-[800px]">
                  <thead>
                    <tr className="border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950">
                      <th className="text-left p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                        Fecha
                      </th>
                      <th className="text-left p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                        Usuario
                      </th>
                      <th className="text-left p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                        Rol
                      </th>
                      <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                        Areas
                      </th>
                      <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                        Total
                      </th>
                      <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                        Finalizadas
                      </th>
                      <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                        Pendientes
                      </th>
                      <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                        Desempeno
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {dailyPerformanceStats.map((row, i) => {
                      const pct =
                        row.total > 0
                          ? Math.round((row.done / row.total) * 100)
                          : 0;
                      const performanceColor =
                        pct >= 80
                          ? "bg-emerald-500"
                          : pct >= 50
                            ? "bg-amber-500"
                            : "bg-red-500";
                      return (
                        <tr
                          key={`${row.date}-${row.userId}`}
                          className={`border-b border-slate-50 dark:border-slate-800/50 ${rowStyle(i)}`}
                        >
                          <td className="p-4 font-mono text-sm font-bold text-slate-700 dark:text-slate-200 whitespace-nowrap">
                            {row.date}
                          </td>
                          <td className="p-4">
                            <p className="font-bold text-slate-800 dark:text-white">
                              {row.name}
                            </p>
                            {row.email && (
                              <p className="text-xs text-slate-500 dark:text-slate-400">
                                {row.email}
                              </p>
                            )}
                          </td>
                          <td className="p-4 text-sm text-slate-500 dark:text-slate-400">
                            {row.roles?.length
                              ? row.roles.join(" / ")
                              : "Usuario"}
                          </td>
                          <td className="p-4">
                            <div className="flex items-center justify-center gap-1.5 flex-wrap">
                              {row.areas.account > 0 && (
                                <span className="px-2 py-1 rounded-lg bg-indigo-50 dark:bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-[11px] font-black">
                                  Account {row.areas.account}
                                </span>
                              )}
                              {row.areas.editing > 0 && (
                                <span className="px-2 py-1 rounded-lg bg-amber-50 dark:bg-amber-500/10 text-amber-600 dark:text-amber-400 text-[11px] font-black">
                                  Edicion {row.areas.editing}
                                </span>
                              )}
                              {row.areas.management > 0 && (
                                <span className="px-2 py-1 rounded-lg bg-violet-50 dark:bg-violet-500/10 text-violet-600 dark:text-violet-400 text-[11px] font-black">
                                  Gestion {row.areas.management}
                                </span>
                              )}
                            </div>
                          </td>
                          <td className="p-4 text-center font-black text-slate-800 dark:text-white">
                            {row.total}
                          </td>
                          <td className="p-4 text-center font-bold text-emerald-600 dark:text-emerald-400">
                            {row.done}
                          </td>
                          <td className="p-4 text-center text-slate-500 dark:text-slate-400">
                            {row.pending}
                          </td>
                          <td className="p-4">
                            <div className="flex items-center justify-center gap-2">
                              <div className="w-20 h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                                <div
                                  className={`h-full rounded-full ${performanceColor}`}
                                  style={{ width: `${pct}%` }}
                                />
                              </div>
                              <span className="w-10 text-right text-sm font-black text-slate-800 dark:text-white">
                                {pct}%
                              </span>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {showSection("managers") && (
        <div
          data-daily-capture-section={expandAllSections ? "reports-managers" : undefined}
          className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden"
        >
          {expandAllSections && (
            <h3 className="px-4 pt-4 text-lg font-black text-slate-800 dark:text-white">
              Por manager
            </h3>
          )}
          {managerStats.length === 0 ? (
            <div className="p-16 text-center text-slate-500 font-bold">
              Sin datos en este rango de fechas
            </div>
          ) : (
            <table className="w-full">
              <thead>
                <tr className="border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950">
                  <th className="text-left p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                    Manager
                  </th>
                  <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                    Total
                  </th>
                  <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                    En Proceso
                  </th>
                  <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                    Aprobadas
                  </th>
                  <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                    Publicadas
                  </th>
                </tr>
              </thead>
              <tbody>
                {managerStats.map((m, i) => (
                  <tr
                    key={m.id}
                    className={`border-b border-slate-50 dark:border-slate-800/50 ${rowStyle(i)}`}
                  >
                    <td className="p-4 font-bold text-slate-800 dark:text-white">
                      {m.name}
                    </td>
                    <td className="p-4 text-center font-black text-slate-800 dark:text-white">
                      {m.total}
                    </td>
                    <td className="p-4 text-center text-slate-500 dark:text-slate-400">
                      {m.inProgress}
                    </td>
                    <td className="p-4 text-center font-bold text-emerald-600 dark:text-emerald-400">
                      {m.approved}
                    </td>
                    <td className="p-4 text-center font-bold text-indigo-600 dark:text-indigo-400">
                      {m.published}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {showSection("editors") && (
        <div
          data-daily-capture-section={expandAllSections ? "reports-editors" : undefined}
          className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden"
        >
          {expandAllSections && (
            <h3 className="px-4 pt-4 text-lg font-black text-slate-800 dark:text-white">
              Por editor
            </h3>
          )}
          {editorStats.length === 0 ? (
            <div className="p-16 text-center text-slate-500 font-bold">
              Sin datos en este rango de fechas
            </div>
          ) : (
            <table className="w-full">
              <thead>
                <tr className="border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950">
                  <th className="text-left p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                    Editor
                  </th>
                  <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                    Total
                  </th>
                  <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                    En Proceso
                  </th>
                  <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                    Aprobadas
                  </th>
                  <th className="text-center p-4 text-xs font-black uppercase tracking-widest text-slate-500">
                    Publicadas
                  </th>
                </tr>
              </thead>
              <tbody>
                {editorStats.map((e, i) => (
                  <tr
                    key={e.id}
                    className={`border-b border-slate-50 dark:border-slate-800/50 ${rowStyle(i)}`}
                  >
                    <td className="p-4 font-bold text-slate-800 dark:text-white">
                      {e.name}
                    </td>
                    <td className="p-4 text-center font-black text-slate-800 dark:text-white">
                      {e.total}
                    </td>
                    <td className="p-4 text-center text-slate-500 dark:text-slate-400">
                      {e.inProgress}
                    </td>
                    <td className="p-4 text-center font-bold text-emerald-600 dark:text-emerald-400">
                      {e.approved}
                    </td>
                    <td className="p-4 text-center font-bold text-indigo-600 dark:text-indigo-400">
                      {e.published}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {showSection("management") && (
        <div
          data-daily-capture-section={expandAllSections ? "reports-management" : undefined}
          className="space-y-4"
        >
          {expandAllSections && (
            <h3 className="text-lg font-black text-slate-800 dark:text-white">
              Gestión
            </h3>
          )}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 p-6">
            <h3 className="font-black text-slate-800 dark:text-white mb-5 flex items-center gap-2">
              <Icon name="ShieldCheck" size={18} className="text-violet-500" />{" "}
              Sala de Gestión
            </h3>
            <div className="space-y-3">
              {[
                { label: "Pendiente", status: "pendiente", color: "slate" },
                { label: "En Proceso", status: "en_proceso", color: "violet" },
                { label: "En Espera", status: "en_espera", color: "amber" },
                { label: "Cerrado", status: "cerrado", color: "emerald" },
              ].map((row) => {
                const count = filteredManagementTasks.filter(
                  (t) => t.status === row.status,
                ).length;
                const pct =
                  filteredManagementTasks.length > 0
                    ? Math.round((count / filteredManagementTasks.length) * 100)
                    : 0;
                return (
                  <div key={row.status}>
                    <div className="flex items-center gap-2 mb-1">
                      <span
                        className={`w-2 h-2 rounded-full bg-${row.color}-500 shrink-0`}
                      />
                      <span className="text-sm text-slate-600 dark:text-slate-300 flex-1">
                        {row.label}
                      </span>
                      <span className="font-black text-slate-800 dark:text-white">
                        {count}
                      </span>
                      <span className="text-xs text-slate-500 w-8 text-right">
                        {pct}%
                      </span>
                    </div>
                    <div className="h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                      <div
                        className={`h-full bg-${row.color}-500 rounded-full transition-all duration-500`}
                        style={{ width: `${pct}%` }}
                      />
                    </div>
                  </div>
                );
              })}
              <div className="pt-3 border-t border-slate-100 dark:border-slate-800 flex justify-between">
                <span className="text-sm font-bold text-slate-500">Total</span>
                <span className="font-black text-slate-800 dark:text-white">
                  {filteredManagementTasks.length}
                </span>
              </div>
            </div>
          </div>
          <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 p-6 flex flex-col gap-4">
            <h3 className="font-black text-slate-800 dark:text-white flex items-center gap-2">
              <Icon name="Flame" size={18} className="text-orange-500" />{" "}
              Resumen
            </h3>
            <ReportStatCard
              label="Tareas Abiertas"
              value={
                filteredManagementTasks.filter((t) => t.status !== "cerrado")
                  .length
              }
              color="violet"
              icon="Circle"
            />
            <ReportStatCard
              label="Tareas Cerradas"
              value={
                filteredManagementTasks.filter((t) => t.status === "cerrado")
                  .length
              }
              color="emerald"
              icon="CheckCircle2"
            />
          </div>
          </div>
        </div>
      )}
    </div>
  );
};

const PerformanceView = ({
  accountTasks = [],
  editingTasks = [],
  managementTasks = [],
  editors = [],
  managers = [],
  users = [],
  periodPreset = "custom",
  isCapturing = false,
  onPeriodPresetChange,
  onRequestDailyCapture,
}) => {
  const todayStr = getHondurasTodayStr();
  const firstOfMonth = getKpiPeriod(todayStr).start;
  const initialLast24h = periodPreset === "last24h" ? getLast24HoursRange() : null;
  const [fromDate, setFromDate] = useState(initialLast24h?.fromDate || firstOfMonth);
  const [toDate, setToDate] = useState(initialLast24h?.toDate || todayStr);
  const [searchTerm, setSearchTerm] = useState("");
  const [personGroupFilter, setPersonGroupFilter] = useState("all");
  const [downloadingPdf, setDownloadingPdf] = useState("");
  const [pdfError, setPdfError] = useState("");
  const [periodMode, setPeriodMode] = useState(
    periodPreset === "last24h" ? "last24h" : "custom",
  );
  const [activityPerson, setActivityPerson] = useState(null);
  const [taskActivityEvents, setTaskActivityEvents] = useState([]);
  const [taskActivityLoading, setTaskActivityLoading] = useState(false);
  const [taskActivityError, setTaskActivityError] = useState("");
  const taskActivityDialogRef = useDialogA11y(Boolean(activityPerson), () => setActivityPerson(null));
  const taskActivityTitleId = useId();
  const [last24hRange, setLast24hRange] = useState(
    () => initialLast24h || getLast24HoursRange(),
  );
  const capturing = Boolean(isCapturing);
  const activeSearchTerm = capturing ? "" : searchTerm;
  const activePersonGroup = capturing ? "all" : personGroupFilter;

  const applyLast24h = useCallback(() => {
    const range = getLast24HoursRange();
    setLast24hRange(range);
    setFromDate(range.fromDate);
    setToDate(range.toDate);
    setPeriodMode("last24h");
    onPeriodPresetChange?.("last24h");
    return range;
  }, [onPeriodPresetChange]);

  useEffect(() => {
    if (periodPreset === "last24h") applyLast24h();
  }, [periodPreset, applyLast24h]);

  const kpiPeriod = useMemo(
    () => ({ start: fromDate, end: toDate }),
    [fromDate, toDate],
  );
  const performanceTasks = useMemo(
    () => buildCompanyTaskList({ tasks: editingTasks, accountTasks, managementTasks }),
    [editingTasks, accountTasks, managementTasks],
  );
  const userById = useMemo(
    () => new Map(users.map((item) => [item.id, item])),
    [users],
  );
  const userByEditorId = useMemo(
    () =>
      new Map(
    users
      .filter((item) => item.linkedEditorId)
      .map((item) => [item.linkedEditorId, item]),
      ),
    [users],
  );
  const userByManagerId = useMemo(
    () =>
      new Map(
    users
      .filter((item) => item.linkedManagerId)
      .map((item) => [item.linkedManagerId, item]),
      ),
    [users],
  );

  useEffect(() => {
    if (!activityPerson?.actorId) return undefined;
    let active = true;
    setTaskActivityLoading(true);
    setTaskActivityError("");
    apiFetch(`/api/activity?actorId=${encodeURIComponent(activityPerson.actorId)}&limit=50`)
      .then((payload) => {
        if (active) setTaskActivityEvents(Array.isArray(payload?.events) ? payload.events : []);
      })
      .catch((error) => {
        if (active) setTaskActivityError(error.message || "No se pudo cargar el registro.");
      })
      .finally(() => {
        if (active) setTaskActivityLoading(false);
      });
    return () => { active = false; };
  }, [activityPerson?.actorId]);

  const getPersonAccessRecency = (personType, personId, personUserId = "") => {
    const personUser =
      personType === "editor"
        ? userByEditorId.get(personId) ||
          (personUserId ? userById.get(personUserId) : null)
        : userByManagerId.get(personId) ||
          (personUserId ? userById.get(personUserId) : null);
    const lastDisconnectedAt = personUser?.lastDisconnectedAt || "";
    return { lastDisconnectedAt };
  };

  const formatLastDisconnect = (value) => {
    const parsed = new Date(value || "");
    if (Number.isNaN(parsed.getTime())) return "Sin registro";
    return new Intl.DateTimeFormat("es-HN", {
      dateStyle: "medium",
      timeStyle: "short",
    }).format(parsed);
  };

  const editorStats = useMemo(
    () =>
      buildTeamKpiStats({
        people: editors.map((person) => ({
          ...userByEditorId.get(person.id), ...person,
          userId: userByEditorId.get(person.id)?.id || person.userId,
          linkedEditorId: person.id,
        })),
        tasks: performanceTasks,
        kind: "editor",
        period: kpiPeriod,
        today: todayStr,
      })
        .filter((editor) => editor.total > 0)
        .map((editor) => {
          const profile = {
            id: editor.userId || editor.id,
            role: "editor",
            linkedEditorId: editor.id,
            email: editor.email,
          };
          const compliance = buildComplianceSnapshot({
            profile,
            accountTasks,
            editingTasks,
            managementTasks,
            today: todayStr,
          });
          const penalizedScore = applyPerformancePenalty(
            editor.score,
            compliance.quotaPenalty,
          );
          return {
            ...editor,
            basePerformance: editor.score,
            overallPerformance: penalizedScore,
            score: penalizedScore,
            compliance,
            quotaPenalty: compliance.quotaPenalty,
            lastDisconnectedAt: getPersonAccessRecency(
              "editor",
              editor.id,
              editor.userId,
            ).lastDisconnectedAt,
          };
        }),
    [
      editors,
      performanceTasks,
      accountTasks,
      editingTasks,
      managementTasks,
      kpiPeriod,
      todayStr,
      userByEditorId,
      userById,
    ],
  );

  const managerStats = useMemo(
    () =>
      buildTeamKpiStats({
        people: managers.map((person) => ({
          ...userByManagerId.get(person.id), ...person,
          userId: userByManagerId.get(person.id)?.id || person.userId,
          linkedManagerId: person.id,
        })),
        tasks: performanceTasks,
        kind: "manager",
        period: kpiPeriod,
        today: todayStr,
      })
        .filter((manager) => manager.total > 0)
        .map((manager) => {
          const profile = {
            id: manager.userId || manager.id,
            role: "manager",
            linkedManagerId: manager.id,
            email: manager.email,
          };
          const compliance = buildComplianceSnapshot({
            profile,
            accountTasks,
            editingTasks,
            managementTasks,
            today: todayStr,
          });
          const penalizedScore = applyPerformancePenalty(
            manager.score,
            compliance.quotaPenalty,
          );
          return {
            ...manager,
            basePerformance: manager.score,
            overallPerformance: penalizedScore,
            score: penalizedScore,
            compliance,
            quotaPenalty: compliance.quotaPenalty,
            lastDisconnectedAt: getPersonAccessRecency(
              "manager",
              manager.id,
              manager.userId,
            ).lastDisconnectedAt,
          };
        }),
    [
      managers,
      performanceTasks,
      accountTasks,
      editingTasks,
      managementTasks,
      kpiPeriod,
      todayStr,
      userByManagerId,
      userById,
    ],
  );

  const developerStats = users
    .filter(
      (person) =>
        person.isActive !== false &&
        TRACKED_DEVELOPER_NAMES.has(normalizeNameKey(person.name)),
    )
    .map((person) => {
      const lastDisconnectedAt = person.lastDisconnectedAt || "";
      return {
        ...person,
        userId: person.id,
        kind: "developer",
        kindLabel: "Desarrollador",
        total: 0,
        delivered: 0,
        published: 0,
        pending: 0,
        overdueTasks: 0,
        weightedTotal: 0,
        weightedCompleted: 0,
        measuredWeight: 0,
        onTimeWeight: 0,
        onTimePercent: null,
        qualified: false,
        deliveryPerformance: 0,
        overallPerformance: 0,
        lastDisconnectedAt,
      };
    });

  const uniquePeople = new Map();
  [...editorStats, ...managerStats, ...developerStats].forEach((person) => {
    const key = person.userId ? `user:${person.userId}` : `${person.kind}:${person.id}`;
    if (!uniquePeople.has(key) || person.kind === person.role) uniquePeople.set(key, person);
  });
  const personStats = [...uniquePeople.values()].sort(
    (left, right) =>
      Number(right.qualified) - Number(left.qualified) ||
      right.overallPerformance - left.overallPerformance ||
      right.weightedCompleted - left.weightedCompleted ||
      String(left.name || "").localeCompare(String(right.name || "")),
  );

  const normalizedSearch = activeSearchTerm.trim().toLowerCase();
  const visiblePersonStats = useMemo(() => {
    let filtered = [...personStats];
    if (activePersonGroup !== "all") {
      filtered = filtered.filter((person) => {
        if (activePersonGroup === "editors") return person.kind === "editor";
        if (activePersonGroup === "managers") return person.kind === "manager";
        return person.kind === "developer";
      });
    }
    if (!normalizedSearch) return filtered;
    return filtered.filter((person) =>
      String(person.name || "").toLowerCase().includes(normalizedSearch),
    );
  }, [normalizedSearch, activePersonGroup, personStats]);

  const visiblePerformanceStats = visiblePersonStats.filter(
    (person) => person.kind !== "developer",
  );
  const qualifiedPerformanceStats = visiblePerformanceStats.filter(
    (person) => person.qualified,
  );
  const averageSource = qualifiedPerformanceStats.length
    ? qualifiedPerformanceStats
    : visiblePerformanceStats;
  const averageWeight = averageSource.reduce(
    (sum, person) => sum + person.weightedTotal,
    0,
  );
  const averagePerformance = calculateKpiScore({
    weightedTotal: averageWeight,
    weightedCompleted: averageSource.reduce((sum, person) => sum + person.weightedCompleted, 0),
    onTimeWeight: averageSource.reduce((sum, person) => sum + person.onTimeWeight, 0),
  });
  const totalTasks = visiblePerformanceStats.reduce(
    (sum, person) => sum + person.total,
    0,
  );
  const deliveredTasks = visiblePerformanceStats.reduce(
    (sum, person) => sum + person.delivered,
    0,
  );
  const measuredWeight = visiblePerformanceStats.reduce(
    (sum, person) => sum + person.measuredWeight,
    0,
  );
  const teamMeasuredCompletionCount = visiblePerformanceStats.reduce(
    (sum, person) => sum + person.measuredCompletionCount,
    0,
  );
  const onTimeWeight = visiblePerformanceStats.reduce(
    (sum, person) => sum + person.onTimeWeight,
    0,
  );
  const teamOnTimePercent =
    measuredWeight && teamMeasuredCompletionCount > 0
    ? Math.round((onTimeWeight / measuredWeight) * 100)
    : null;
  const overdueTasks = visiblePerformanceStats.reduce(
    (sum, person) => sum + person.overdueTasks,
    0,
  );
  const deliveryRate = totalTasks
    ? Math.round((deliveredTasks / totalTasks) * 100)
    : 0;
  const peopleNeedingAttention = visiblePersonStats.filter(
    (person) =>
      person.kind !== "developer" &&
      (person.overdueTasks > 0 ||
        (person.qualified && person.overallPerformance < 60)),
  ).length;
  const groupLabel =
    activePersonGroup === "editors"
      ? "Editores"
      : activePersonGroup === "managers"
        ? "Community Managers"
        : activePersonGroup === "developers"
          ? "Desarrolladores"
        : "Todo el equipo";

  const downloadReportPdf = async (report) => {
    if (!report || downloadingPdf) return;
    setPdfError("");
    setDownloadingPdf(report.id);
    try {
      await downloadAuthenticatedPdf(report.path, report.file);
    } catch (error) {
      setPdfError(error.message || "No se pudo generar el PDF");
    } finally {
      setDownloadingPdf("");
    }
  };

  return (
    <section
      className={`performance-dashboard fade-in ${capturing ? "is-capturing" : ""}`}
    >
      <header className="performance-header">
        <div className="performance-heading">
          <p className="eyebrow">Editores, Community Managers y desarrolladores</p>
          <h2>Rendimiento del equipo</h2>
          <p>
            Revisa las entregas, los pendientes y el cumplimiento del equipo.
          </p>
          {periodMode === "last24h" && (
            <div className="performance-daily-stamp">
              Reporte diario · últimas 24 horas · {last24hRange.periodLabel}
            </div>
          )}
        </div>

        <div className="performance-header-tools">
        <div className="performance-period" aria-label="Rango del reporte">
            <button
              type="button"
              className={periodMode === "last24h" ? "is-active" : ""}
              onClick={applyLast24h}
            >
              Últimas 24h
            </button>
          <label>
            <span>Desde</span>
            <input
              type="date"
              value={fromDate}
                onChange={(event) => {
                  setPeriodMode("custom");
                  onPeriodPresetChange?.("custom");
                  setFromDate(event.target.value);
                }}
            />
          </label>
          <span aria-hidden="true">→</span>
          <label>
            <span>Hasta</span>
            <input
              type="date"
              value={toDate}
                onChange={(event) => {
                  setPeriodMode("custom");
                  onPeriodPresetChange?.("custom");
                  setToDate(event.target.value);
                }}
            />
          </label>
          </div>
          <div
            className="performance-downloads"
            aria-label="Descargar informes"
          >
            <p>
              <Icon name="Download" size={14} />
              Descargar informes
            </p>
            <div>
              <button
                type="button"
                onClick={() => onRequestDailyCapture?.()}
                disabled={capturing || !onRequestDailyCapture}
              >
                {capturing ? (
                  <Icon name="Loader2" size={13} className="animate-spin" />
                ) : (
                  <Icon name="FileText" size={13} />
                )}
                Descargar PDF de Rendimiento
              </button>
              {["Diario", "Semanal"].map((group) => (
                <span key={group} className="performance-download-group">
                  <span>{group}</span>
                  {PERFORMANCE_REPORT_PDFS.filter((item) => item.group === group).map(
                    (report) => (
                      <button
                        key={report.id}
                        type="button"
                        onClick={() => downloadReportPdf(report)}
                        disabled={Boolean(downloadingPdf)}
                      >
                        {downloadingPdf === report.id ? (
                          <Icon
                            name="Loader2"
                            size={13}
                            className="animate-spin"
                          />
                        ) : null}
                        {report.label}
                      </button>
                    ),
                  )}
                </span>
              ))}
            </div>
          </div>
          {pdfError ? (
            <p className="performance-download-error">{pdfError}</p>
          ) : null}
        </div>
      </header>

      <section
        className="performance-overview"
        aria-label="Resumen de rendimiento"
      >
        <div className="performance-primary-metric">
          <p>KPI promedio</p>
          <strong>{averagePerformance}%</strong>
          <span>
            {groupLabel} · {visiblePersonStats.length} personas
          </span>
          <small>
            70% entregado + 30% a tiempo. El ritmo de producción, revisión y aprobación ajusta un 25% de la nota
          </small>
        </div>

        <dl className="performance-metric-list">
          <div>
            <dt>Entregadas</dt>
            <dd>
              {deliveredTasks}
              <span>/{totalTasks}</span>
            </dd>
            <small>{deliveryRate}% del trabajo</small>
          </div>
          <div>
            <dt>Puntualidad</dt>
            <dd>{teamOnTimePercent === null ? "N/D" : `${teamOnTimePercent}%`}</dd>
            <small>solo entregas con fecha comprobable</small>
          </div>
          <div className={peopleNeedingAttention > 0 ? "has-attention" : ""}>
            <dt>Necesitan atención</dt>
            <dd>{peopleNeedingAttention}</dd>
            <small>{overdueTasks} tareas vencidas</small>
          </div>
        </dl>
      </section>

      <div className="performance-toolbar">
        <div
          className="performance-group-filter"
          role="tablist"
          aria-label="Filtrar por función"
        >
          {[
            { id: "all", label: "Todos" },
            { id: "editors", label: "Editores" },
            { id: "managers", label: "Community Managers" },
            { id: "developers", label: "Desarrolladores" },
          ].map((option) => (
            <button
              key={option.id}
              type="button"
              role="tab"
              aria-selected={personGroupFilter === option.id}
              className={personGroupFilter === option.id ? "is-active" : ""}
              onClick={() => setPersonGroupFilter(option.id)}
            >
              {option.label}
            </button>
          ))}
        </div>

        <div className="performance-search-wrap">
          <label className="performance-search">
            <Icon name="Search" size={16} />
            <input
              value={searchTerm}
              onChange={(event) => setSearchTerm(event.target.value)}
              placeholder="Buscar persona"
              aria-label="Buscar persona"
            />
            {searchTerm && (
              <button
                type="button"
                onClick={() => setSearchTerm("")}
                aria-label="Limpiar búsqueda"
              >
                <Icon name="X" size={14} />
              </button>
            )}
          </label>
          {(searchTerm || personGroupFilter !== "all") && (
            <button
              type="button"
              className="performance-reset"
              onClick={() => {
                setSearchTerm("");
                setPersonGroupFilter("all");
              }}
            >
              Limpiar filtros
            </button>
          )}
        </div>
      </div>

      <section
        className="performance-ranking"
        aria-labelledby="performance-ranking-title"
      >
        <header className="performance-ranking-header">
          <div>
            <h3 id="performance-ranking-title">Equipo</h3>
            <p>Las mediciones consolidadas aparecen primero; se requieren {KPI_MIN_TASKS} tareas y fechas verificables en las entregas.</p>
          </div>
          <span>{visiblePersonStats.length} resultados</span>
        </header>

        {visiblePersonStats.length === 0 ? (
          <div className="performance-empty">
            <span>
              <Icon name="Users" size={20} />
            </span>
            <div>
              <strong>Sin resultados</strong>
              <p>Ajusta la búsqueda, el equipo o el rango de fechas.</p>
            </div>
          </div>
        ) : (
          <div className="performance-person-list">
            <div className="performance-column-head" aria-hidden="true">
              <span />
              <span>Persona</span>
              <span>KPI</span>
              <span>A tiempo</span>
              <span>Pendientes</span>
              <span>Actividad</span>
            </div>

            {visiblePersonStats.map((person, index) => {
              const initials = String(person.name || "Usuario")
                .trim()
                .split(/\s+/)
                .slice(0, 2)
                .map((part) => part[0])
                .join("")
                .toUpperCase();
              const activityLabel = formatLastDisconnect(
                person.lastDisconnectedAt,
              );
              const activityActorId = person.userId
                || userByManagerId.get(person.managerId || person.id)?.id
                || userByEditorId.get(person.editorId || person.id)?.id
                || person.id;
              const scoreTone =
                person.overallPerformance >= 80
                  ? "is-strong"
                  : person.overallPerformance >= 60
                    ? "is-steady"
                    : "is-attention";

              return (
                <article
                  key={`${person.kind}-${person.id}`}
                  className={`performance-person-row ${index === 0 ? "is-leading" : ""}`}
                  aria-label={
                    person.kind === "developer"
                      ? `${person.name}: última desconexión ${activityLabel}`
                      : `${person.name}: KPI ${person.overallPerformance}%`
                  }
                >
                  <span className="performance-rank">
                    {person.kind === "developer" || !person.qualified
                      ? "—"
                      : `#${index + 1}`}
                  </span>

                  <div className="performance-person">
                    <span className="performance-avatar" aria-hidden="true">
                      {initials}
                    </span>
                    <span>
                      <strong>{person.name}</strong>
                      <small>{person.kindLabel}</small>
                    </span>
                  </div>

                  <div className={`performance-person-kpi ${scoreTone}`}>
                    {person.kind === "developer" ? (
                      <span>
                        <strong>—</strong>
                        <small>seguimiento de acceso</small>
                      </span>
                    ) : (
                      <>
                    <span>
                      <strong>{person.overallPerformance}%</strong>
                          <small>
                            {person.quotaPenalty > 0 ? (
                              <span className="block font-semibold text-red-400">
                                −{person.quotaPenalty} pts sanción (base {person.basePerformance}%)
                              </span>
                            ) : null}
                            {person.qualified
                              ? `${person.deliveryPerformance}% cumplimiento`
                              : `Provisional · ${person.provisionalReason}`}
                            {person.paceScore != null ? ` · ${person.paceScore}% ritmo` : ""}
                          </small>
                    </span>
                    <span className="performance-kpi-track" aria-hidden="true">
                      <span
                        style={{
                          width: `${person.overallPerformance}%`,
                          height: "100%",
                          display: "block",
                          backgroundColor:
                            person.overallPerformance >= 80
                              ? "#397653"
                              : person.overallPerformance >= 60
                                ? "#b7791f"
                                : "#bd4545",
                        }}
                      />
                    </span>
                      </>
                    )}
                  </div>

                  <div className="performance-person-output">
                    {person.kind === "developer" ? (
                      <><strong>—</strong><small>sin tareas editoriales</small></>
                    ) : (
                      <>
                    <strong>
                          {person.measuredCompletionCount > 0 &&
                          person.onTimePercent !== null
                            ? `${person.onTimePercent}%`
                            : "N/D"}
                    </strong>
                        <small>
                          {person.measuredCompletionCount}/{person.completed} entregas con fecha
                        </small>
                      </>
                    )}
                  </div>

                  <div
                    className={`performance-person-pending ${person.pending > 0 ? "has-pending" : ""}`}
                  >
                    {person.kind === "developer" ? (
                      <><strong>—</strong><small>no aplica</small></>
                    ) : (
                      <>
                    <strong>{person.pending}</strong>
                        <small>{person.overdueTasks} vencidas</small>
                      </>
                    )}
                  </div>

                  <div className="performance-person-activity">
                    <strong>Última desconexión</strong>
                    <small>{activityLabel}</small>
                    <button
                      type="button"
                      onClick={() => {
                        setTaskActivityEvents([]);
                        setActivityPerson({ actorId: activityActorId, name: person.name });
                      }}
                      className="mt-1 text-xs font-black text-indigo-600 underline-offset-2 hover:underline dark:text-indigo-300"
                    >
                      Ver registro
                    </button>
                  </div>
                </article>
              );
            })}
          </div>
        )}
      </section>
      {activityPerson && (
        <div
          className="fixed inset-0 z-[135] flex items-center justify-center bg-slate-950/60 p-4 backdrop-blur-sm"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget) setActivityPerson(null);
          }}
        >
          <section
            ref={taskActivityDialogRef}
            role="dialog"
            aria-modal="true"
            aria-labelledby={taskActivityTitleId}
            tabIndex={-1}
            className="w-full max-w-2xl overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-2xl dark:border-slate-700 dark:bg-slate-900"
          >
            <header className="flex items-center justify-between border-b border-slate-100 px-6 py-5 dark:border-slate-800">
              <div>
                <p className="text-xs font-black uppercase tracking-widest text-indigo-500">Actividad de tareas</p>
                <h2 id={taskActivityTitleId} className="mt-1 text-xl font-black text-slate-900 dark:text-white">{activityPerson.name}</h2>
                <p className="mt-1 text-sm text-slate-500">Tareas que abrió o modificó, con fecha y hora.</p>
              </div>
              <button type="button" onClick={() => setActivityPerson(null)} aria-label="Cerrar actividad" className="rounded-xl p-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800">
                <Icon name="X" />
              </button>
            </header>
            <div className="max-h-[min(70vh,620px)] overflow-y-auto p-5">
              {taskActivityLoading ? (
                <div className="py-12 text-center text-sm font-bold text-slate-500">Cargando actividad…</div>
              ) : taskActivityError ? (
                <div role="alert" className="rounded-2xl bg-red-50 p-4 text-sm font-semibold text-red-700 dark:bg-red-500/10 dark:text-red-300">{taskActivityError}</div>
              ) : taskActivityEvents.length === 0 ? (
                <div className="py-12 text-center text-sm font-semibold text-slate-500">Aún no hay movimientos para mostrar.</div>
              ) : (
                <ol className="space-y-3">
                  {taskActivityEvents.map((event) => {
                    const actionLabel = ({ opened: "Abrió", created: "Creó", updated: "Modificó", deleted: "Eliminó" })[event.action] || "Actualizó";
                    const date = new Date(event.createdAt || "");
                    const timestamp = Number.isNaN(date.getTime()) ? "Fecha no disponible" : new Intl.DateTimeFormat("es-HN", { dateStyle: "medium", timeStyle: "short", timeZone: "America/Tegucigalpa" }).format(date);
                    return (
                      <li key={event.id} className="flex gap-3 rounded-2xl border border-slate-100 p-4 dark:border-slate-800">
                        <span className={`mt-0.5 grid h-9 w-9 shrink-0 place-items-center rounded-xl ${event.action === "opened" ? "bg-sky-50 text-sky-600 dark:bg-sky-500/10 dark:text-sky-300" : "bg-indigo-50 text-indigo-600 dark:bg-indigo-500/10 dark:text-indigo-300"}`}>
                          <Icon name={event.action === "opened" ? "Eye" : "Pencil"} size={16} />
                        </span>
                        <span className="min-w-0 flex-1">
                          <strong className="text-sm font-black text-slate-800 dark:text-white">{actionLabel}: {event.taskTitle}</strong>
                          {event.fields?.length > 0 && (
                            <small className="mt-1 block text-slate-500">Campos: {event.fields.join(", ")}</small>
                          )}
                          <time dateTime={event.createdAt} className="mt-2 block text-xs font-semibold text-slate-400">{timestamp}</time>
                        </span>
                      </li>
                    );
                  })}
                </ol>
              )}
            </div>
          </section>
        </div>
      )}
    </section>
  );
};

const NotificationCenter = ({
  isOpen,
  notifications = [],
  unreadCount = 0,
  onClose,
  onSelect,
  onMarkAllRead,
  onRefresh,
}) => {
  const dialogRef = useDialogA11y(isOpen, onClose);
  const titleId = useId();
  useEffect(() => {
    if (isOpen) void onRefresh?.();
  }, [isOpen, onRefresh]);
  if (!isOpen) return null;

  const formatCreatedAt = (value) => {
    const date = new Date(value || "");
    if (Number.isNaN(date.getTime())) return "Fecha no disponible";
    return new Intl.DateTimeFormat("es-HN", {
      dateStyle: "medium",
      timeStyle: "short",
      timeZone: "America/Tegucigalpa",
    }).format(date);
  };

  return (
    <div
      className="fixed inset-0 z-[130] flex items-center justify-center bg-slate-950/60 p-4 backdrop-blur-sm"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose?.();
      }}
    >
      <section
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        tabIndex={-1}
        className="w-full max-w-xl overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-2xl dark:border-slate-700 dark:bg-slate-900"
      >
        <header className="flex items-center justify-between border-b border-slate-100 px-6 py-5 dark:border-slate-800">
          <div>
              <p className="text-xs font-black uppercase tracking-widest text-amber-500">Avisos del equipo</p>
            <h2 id={titleId} className="mt-1 text-xl font-black text-slate-900 dark:text-white">Notificaciones</h2>
              <p className="mt-1 text-sm text-slate-500">{unreadCount} sin leer</p>
          </div>
          <div className="flex items-center gap-2">
            {unreadCount > 0 && (
              <button type="button" onClick={onMarkAllRead} className="rounded-xl px-3 py-2 text-xs font-bold text-indigo-600 hover:bg-indigo-50 dark:text-indigo-300 dark:hover:bg-indigo-500/10">
                Marcar todas leídas
              </button>
            )}
            <button type="button" onClick={onClose} aria-label="Cerrar notificaciones" className="rounded-xl p-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800">
              <Icon name="X" />
            </button>
          </div>
        </header>
        <div className="max-h-[min(70vh,620px)] overflow-y-auto p-3">
          {notifications.length === 0 ? (
            <div className="px-6 py-16 text-center">
              <span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-slate-100 text-slate-500 dark:bg-slate-800"><Icon name="Bell" size={22} /></span>
              <strong className="mt-4 block text-slate-800 dark:text-white">Todo al día</strong>
              <p className="mt-1 text-sm text-slate-500">Aquí verás las tareas que te asignen, las menciones y otros avisos.</p>
            </div>
          ) : notifications.map((item) => (
            <button
              key={item.id}
              type="button"
              onClick={() => onSelect?.(item)}
              className={`flex w-full gap-3 rounded-2xl p-4 text-left transition hover:bg-slate-50 dark:hover:bg-slate-800/70 ${item.readAt ? "opacity-75" : "bg-amber-50/70 dark:bg-amber-500/5"}`}
            >
              <span className={`mt-1 h-2.5 w-2.5 shrink-0 rounded-full ${item.readAt ? "bg-slate-300 dark:bg-slate-600" : "bg-amber-500"}`} />
              <span className="min-w-0 flex-1">
                <span className="flex items-start justify-between gap-3">
                  <strong className="text-sm font-black text-slate-800 dark:text-white">{item.title}</strong>
                  <small className="shrink-0 text-[11px] text-slate-400">{formatCreatedAt(item.createdAt)}</small>
                </span>
                <span className="mt-1 block text-sm leading-5 text-slate-600 dark:text-slate-300">{item.body}</span>
                <small className="mt-2 block text-xs font-semibold text-slate-400">{item.actorName}</small>
              </span>
            </button>
          ))}
        </div>
      </section>
    </div>
  );
};

const root = createRoot(document.getElementById("root"));
root.render(
  <AppErrorBoundary>
    <App />
  </AppErrorBoundary>,
);
